import{r as i,u as k,a as y,j as e,d as j}from"./index.js";function A({title:r,kicker:s,onClose:a,children:h,wide:c,allowFullscreen:g}){const o=i.useRef(null),{locale:d}=k(),u=y(d).modals,[t,m]=i.useState(!1);i.useEffect(()=>{const n=document.body.style.overflow,w=document.documentElement.style.overflow;document.body.style.overflow="hidden",document.documentElement.style.overflow="hidden";const l=b=>{b.key==="Escape"&&a()};return window.addEventListener("keydown",l),o.current?.querySelector("button, [href], input, [tabindex]")?.focus(),()=>{window.dispatchEvent(new CustomEvent("stopAllAudio")),window.removeEventListener("keydown",l),document.body.style.overflow=n,document.documentElement.style.overflow=w}},[a]),i.useEffect(()=>{const n=()=>{m(!!document.fullscreenElement),setTimeout(()=>window.dispatchEvent(new Event("resize")),100)};return document.addEventListener("fullscreenchange",n),()=>document.removeEventListener("fullscreenchange",n)},[]);const v=()=>{document.fullscreenElement?document.exitFullscreen():o.current?.parentElement?.requestFullscreen().catch(n=>console.error(n))},p=t?"fixed inset-0 m-0 h-screen w-screen max-w-none max-h-none rounded-none border-0":`relative max-h-[88vh] w-full ${c?"w-[95vw] max-w-[1600px] h-[90vh]":"max-w-[620px]"} p-6`,f=t?"p-4 md:p-6":"";return e.jsx("div",{"code-path":"src/components/ModalShell.tsx:68:5",className:`overlay-backdrop flex items-center justify-center ${t?"p-0":"p-4"}`,onClick:a,role:"presentation",children:e.jsxs("div",{"code-path":"src/components/ModalShell.tsx:69:7",ref:o,role:"dialog","aria-modal":"true","aria-label":r,className:`modal-panel bible-scroll flex flex-col overflow-hidden ${p} ${f}`,onClick:n=>n.stopPropagation(),children:[e.jsxs("div",{"code-path":"src/components/ModalShell.tsx:77:9",className:"mb-4 flex-none flex items-start justify-between gap-4 border-b border-line-warm pb-4",children:[e.jsxs("div",{"code-path":"src/components/ModalShell.tsx:78:11",children:[s&&e.jsx("div",{"code-path":"src/components/ModalShell.tsx:79:24",className:"kicker",children:s}),e.jsx("h2",{"code-path":"src/components/ModalShell.tsx:80:13",className:"font-display mt-1 text-[1.7rem] font-bold leading-none text-ink",children:r})]}),e.jsxs("div",{"code-path":"src/components/ModalShell.tsx:82:11",className:"flex gap-2",children:[g&&e.jsx("button",{"code-path":"src/components/ModalShell.tsx:84:17",onClick:v,className:"flex-none rounded-lg border border-line-warm bg-surface p-2 text-ink-muted transition-colors hover:border-line-strong hover:text-ink",title:d==="nl"?"Volledig Scherm":"Fullscreen",children:t?e.jsx("svg",{"code-path":"src/components/ModalShell.tsx:90:25",width:"16",height:"16",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor",strokeWidth:"2",children:e.jsx("path",{"code-path":"src/components/ModalShell.tsx:90:123",d:"M8 3v3a2 2 0 0 1-2 2H3m18 0h-3a2 2 0 0 1-2-2V3m0 18v-3a2 2 0 0 1 2-2h3M3 16h3a2 2 0 0 1 2 2v3"})}):e.jsx("svg",{"code-path":"src/components/ModalShell.tsx:92:25",width:"16",height:"16",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor",strokeWidth:"2",children:e.jsx("path",{"code-path":"src/components/ModalShell.tsx:92:123",d:"M8 3H5a2 2 0 0 0-2 2v3m18 0V5a2 2 0 0 0-2-2h-3m0 18h3a2 2 0 0 0 2-2v-3M3 16v3a2 2 0 0 0 2 2h3"})})}),e.jsx("button",{"code-path":"src/components/ModalShell.tsx:96:13",onClick:a,className:"flex-none rounded-lg border border-line-warm bg-surface p-2 text-ink-muted transition-colors hover:border-line-strong hover:text-ink","aria-label":u.close,children:e.jsx(j,{"code-path":"src/components/ModalShell.tsx:101:15",className:"h-4 w-4"})})]})]}),e.jsx("div",{"code-path":"src/components/ModalShell.tsx:107:9",className:"bible-scroll flex-1 min-h-0 flex flex-col relative overflow-y-auto",children:h})]})})}const T=[{id:"tyrus",coords:[33.273333,35.193611],name:{nl:"Tyrus",en:"Tyre"},region:{nl:"Fenicië",en:"Phoenicia"},desc:{nl:"Machtige Fenicische handelsstad.",en:"Powerful Phoenician trade city."},story:{nl:"Tyrus was het kloppende hart van het Fenicische zee-imperium. Koning Hiram van Tyrus was een bondgenoot van David en Salomo en leverde het beroemde cederhout en de vaklieden voor de bouw van de Eerste Tempel. Later werd Tyrus zwaar veroordeeld door de profeten vanwege haar enorme hoogmoed en afgoderij (Ezechiël 26-28).",en:"Tyre was the beating heart of the Phoenician maritime empire. King Hiram of Tyre was an ally of David and Solomon, providing the famous cedar wood and craftsmen for the construction of the First Temple. Later, Tyre was heavily condemned by the prophets for its massive pride and idolatry (Ezekiel 26-28)."},eras:[4,6,7]},{id:"alexandria",coords:[31.2,29.916667],name:{nl:"Alexandrië",en:"Alexandria"},region:{nl:"Egypte (Griekse Rijk)",en:"Egypt (Hellenistic Empire)"},desc:{nl:"Hoofdstad van het Grieks-Egyptische Rijk.",en:"Capital of the Greco-Egyptian Empire."},story:{nl:"Gesticht door Alexander de Grote. Tijdens de Tweede Tempelperiode (het Griekse Rijk) woonde hier de grootste Joodse gemeenschap buiten Israël. Hier werd de Hebreeuwse Bijbel vertaald naar het Grieks (de Septuaginta), wat cruciaal was voor de verspreiding van het evangelie door de vroege kerk.",en:"Founded by Alexander the Great. During the Second Temple Period (the Hellenistic Empire), this was home to the largest Jewish community outside Israel. Here, the Hebrew Bible was translated into Greek (the Septuagint), which was crucial for the spread of the gospel by the early church."},eras:[6]},{id:"memphis",coords:[29.849722,31.253611],name:{nl:"Memphis",en:"Memphis"},region:{nl:"Oude Egypte",en:"Ancient Egypt"},desc:{nl:"Oude hoofdstad van het Egyptische Rijk.",en:"Ancient capital of the Egyptian Empire."},story:{nl:"Memphis was eeuwenlang de glorieuze hoofdstad van het Egyptische wereldrijk. Tijdens de periode van de Aartsvaders en de Uittocht was dit het centrum van faraonische macht en afgoderij. De rijkdom en architectuur (zoals de nabijgelegen piramides) vormden een schril contrast met de slavernij van de Israëlieten.",en:"For centuries, Memphis was the glorious capital of the Egyptian world empire. During the time of the Patriarchs and the Exodus, it was the center of pharaonic power and idolatry. Its wealth and architecture (such as the nearby pyramids) stood in stark contrast to the slavery of the Israelites."},eras:[2,3]},{id:"ararat",coords:[39.701944,44.297222],name:{nl:"Ararat Gebergte",en:"Mount Ararat"},region:{nl:"Armenië",en:"Armenia"},desc:{nl:"De rustplaats van de Ark van Noach.",en:"The resting place of Noah's Ark."},story:{nl:"Na maanden op het allesvernietigende vloedwater te hebben gedreven, liep de Ark van Noach vast op het gebergte van Ararat (Genesis 8:4). Vanaf deze hoogvlakte begon de mensheid opnieuw. Noach bouwde hier een altaar en God sloot het verbond van de regenboog, met de belofte de aarde nooit meer door water te vernietigen.",en:"After floating on the devastating floodwaters for months, Noah's Ark came to rest on the mountains of Ararat (Genesis 8:4). From this high plateau, humanity began anew. Noah built an altar here and God made the covenant of the rainbow, promising never to destroy the earth by water again."},eras:[1]},{id:"tabor",coords:[32.686111,35.39],name:{nl:"Berg Tabor",en:"Mount Tabor"},region:{nl:"Galilea",en:"Galilee"},desc:{nl:"De traditionele berg van Jezus' verheerlijking.",en:"The traditional mount of Jesus' transfiguration."},story:{nl:"Berg Tabor verheft zich indrukwekkend uit de vlakte van Jizreël. Theologisch en traditioneel is dit de berg der Verheerlijking, waar Jezus voor de ogen van Petrus, Jakobus en Johannes straalde van goddelijk licht. Mozes en Elia verschenen hier om met Hem te spreken over Zijn naderende vertrek (kruisiging) in Jeruzalem, wat de Wet en de Profeten samenbracht in Christus (Mattheüs 17).",en:"Mount Tabor rises impressively from the Jezreel Valley. Theologically and traditionally, this is the Mount of Transfiguration, where Jesus shone with divine light before the eyes of Peter, James, and John. Moses and Elijah appeared here to speak with Him about His upcoming departure (crucifixion) in Jerusalem, bringing the Law and the Prophets together in Christ (Matthew 17)."},eras:[6]},{id:"promised_land",coords:[32.766667,35.333333],name:{nl:"Het Beloofde Land",en:"The Promised Land"},region:{nl:"Kanaän",en:"Canaan"},desc:{nl:"Het land dat God aan Abraham en zijn nageslacht beloofde.",en:"The land promised by God to Abraham and his descendants."},story:{nl:`**Geografische en historische context**
Het kerngebied van het Beloofde Land ligt geografisch strategisch tussen de Middellandse Zee (westen) en de Jordaanvallei, begrensd door de Syrische woestijn in het oosten, het Libanongebergte in het noorden en de Negev-woestijn in het zuiden. Historisch en geografisch omvat dit gebied het huidige Israël, de Palestijnse gebieden, en grote delen van Jordanië, Libanon en Syrië. Omdat het fungeerde als enige landbrug tussen de twee grootmachten van de oudheid (Egypte en Mesopotamië), had het een immense economische en militaire waarde.

**De grenzen van de belofte**
De exacte geografische grenzen van het land verschillen per bijbelboek en periode. In Genesis 15:18 krijgt Abraham de "brede definitie" (de landbelofte) toegezegd: een enorm uitgestrekt gebied vanaf de "Rivier van Egypte" (waarschijnlijk de Wadi El-Arish in het Sinaï-schiereiland) tot aan de Eufraat (in het huidige Syrië/Irak). Later, in Numeri 34, wanneer het volk Kanaän daadwerkelijk gaat verdelen, krijgen zij de "specifieke grenzen" toegewezen: een compacter gebied met in het zuiden de Zin-woestijn, in het westen de Middellandse Zee, in het noorden de berg Hor, en in het oosten de rivier de Jordaan (hoewel er later gebieden ten oosten van de Jordaan aan werden toegevoegd).

**Theologische betekenis**
Het Beloofde Land is veel meer dan een stuk geografisch onroerend goed; het is het tastbare bewijs van Gods onwankelbare verbondstrouw aan Abraham, Isaäk en Jakob. God gaf dit specifieke, kwetsbare land (volledig afhankelijk van regen, in tegenstelling tot Egypte) zodat Zijn volk in dagelijkse afhankelijkheid van Hem zou leven. Het is bedoeld als een 'licht voor de volken' en wijst in het Nieuwe Testament (bijv. Hebreeën 4) vooruit naar de eeuwige rust en de herstelde schepping.`,en:`**Archaeological and historical significance**
The Promised Land sits strategically between the Mediterranean Sea and the vast deserts to the east. It forms the primary land bridge connecting Africa, Asia, and Europe, making it one of the most contested and historically rich regions in antiquity.

**Cultural and geographical context**
Known variously as Canaan, Israel, and Palestine, it is a land of immense geographical diversity, featuring fertile plains, rugged mountains, and the lowest point on earth (the Dead Sea). It was described by God as a land "flowing with milk and honey", indicating rich agricultural potential and divine provision.

**Theological significance**
The Promised Land is the geographic center of biblical theology. It was sworn by covenant to Abraham, Isaac, and Jacob as an everlasting inheritance. Theologically, it represents rest, divine inheritance, and the kingdom of God on earth. Its possession was strictly tied to Israel's faithfulness to the covenant; disobedience led to exile, while repentance promised return. Ultimately, it foreshadows the new creation and the eternal rest promised to all believers in Christ.`},verses:["Genesis 15:18","Numeri 34:1","Jozua 1:4"],eras:[2,3]},{id:"jerusalem",coords:[31.776667,35.234167],name:{nl:"Jeruzalem",en:"Jerusalem"},region:{nl:"Juda",en:"Judah"},desc:{nl:"De heilige stad en hoofdstad van Israël.",en:"The holy city and capital of Israel."},story:{nl:`**Archeologische en historische betekenis**
Jeruzalem ligt op een verdedigbare heuvelrug in het Judese hoogland, met archeologische bewijzen van bewoning die dateren uit de vroege bronstijd, hoewel de stad pas echt tot bloei kwam tijdens de IJzertijd II (10e-8e eeuw v.Chr.). De Gihonbron zorgde voor essentiële watervoorziening, waardoor de locatie strategisch waardevol was; opgravingen hebben vestingwerken en administratieve structuren uit de tijd van David en de latere monarchie aan het licht gebracht, wat de rol van Jeruzalem als belangrijk administratief centrum in het oude Juda bevestigt.

**Culturele en geografische context**
Jeruzalem, gelegen op een hoogte van ongeveer 760 meter in het centrale heuvelland, beheerste cruciale handelsroutes tussen de kustgebieden en de Jordaanvallei, waardoor het gedurende de Bijbelse periode economisch en militair van groot belang was. De natuurlijke verdedigingskracht van de stad door valleien aan drie zijden (de Kidronvallei, de Hinnomvallei en de Tyropoeonvallei) maakte haar vrijwel onneembaar voor een directe aanval. Dit verklaart waarom het een Jebusitisch bolwerk bleef tot de verovering door David en waarom het de gekozen hoofdstad werd van de verenigde monarchie.

**Theologische betekenis**
Jeruzalem komt in het boek Jozua naar voren als een van de vijf Amorietische koningen die in de zuidelijke veldtocht werden verslagen, waarmee het wordt gevestigd als een veroverde, maar aanvankelijk niet-veroverde stad binnen Israëls territoriale aanspraken. De theologische betekenis van de stad neemt toe wanneer David haar verovert en vestigt als Israëls politieke en religieuze hoofdstad. Het wordt uiteindelijk de locatie van Salomo's Tempel en het middelpunt van de verbondsaanbidding – een status die Jeruzalem in de hele Schrift verheft tot de woonplaats van Gods aanwezigheid en het symbool van Zijn koninkrijk op aarde.`,en:`**Archaeological and historical significance**
Jerusalem sits on a defensible ridge in the Judean highlands. Since King David captured it from the Jebusites around 1000 BC, it has been the political and religious epicenter of Israel. Archaeological digs continually reveal its massive ancient walls, water systems, and temple foundations.

**Cultural and geographical context**
Positioned off the main international trade routes, Jerusalem's significance was entirely theological and political rather than economic. It is surrounded by deep valleys (Kidron and Hinnom), making it a natural fortress. Mount Moriah, where Abraham bound Isaac, became the site of Solomon's magnificent Temple.

**Theological significance**
Jerusalem is the "City of the Great King" and the earthly dwelling place of God's name. It is the site of the crucifixion, resurrection, and ascension of Jesus Christ, and the birthplace of the Church at Pentecost. Prophetically, it is the focal point of end-time events and the namesake of the eternal New Jerusalem, representing the ultimate dwelling of God with His people.`},verses:["Jozua 10:1","2 Samuël 5:6","1 Koningen 8:1","Psalm 122:1","Zacharia 8:3","Mattheüs 23:37","Openbaring 21:2"],eras:[4,6,7]},{id:"rephidim",coords:[28.623056,33.880278],name:{nl:"Rafidim",en:"Rephidim"},region:{nl:"Sinaï",en:"Sinai"},desc:{nl:"De rustplaats waar water uit de rots stroomde en Amalek werd verslagen.",en:"The resting place where water flowed from the rock and Amalek was defeated."},story:{nl:`**Archeologische en historische betekenis**
De exacte locatie van Rafidim is niet met zekerheid vastgesteld, maar historisch wordt het vaak geïdentificeerd met Wadi Feiran, een weelderige oase in het zuidwesten van het Sinaï-schiereiland. Archeologische vondsten tonen aan dat dit gebied al vroeg bewoond werd en diende als een belangrijke doorgangsroute. Het was een logische rustplaats voor nomaden en reizigers, wat verklaart waarom de Amalekieten, een lokaal nomadenvolk, dit gebied fel verdedigden tegen de doortrekkende Israëlieten.

**Culturele en geografische context**
Geografisch was Rafidim de laatste grote rustplaats voordat het volk Israël de berg Sinaï bereikte. De afwezigheid van water bij hun aankomst zorgde voor een crisis in het genadeloze woestijnklimaat. Cultureel markeert dit moment de eerste georganiseerde militaire strijd van het pas bevrijde volk; Jozua leidde de troepen in het dal, terwijl Mozes, Aäron en Hur de strijd vanaf de heuvel geestelijk ondersteunden.

**Theologische betekenis**
Theologisch is Rafidim zeer rijk. Ten eerste het water uit de rots: toen het volk murmureerde, beval God Mozes om op de rots (Horeb) te slaan. De apostel Paulus identificeert deze geslagen rots later met Christus (1 Korinthe 10:4), die levend water geeft nadat Hij geslagen is. Ten tweede de strijd tegen Amalek: dit illustreert de voortdurende geestelijke strijd. De overwinning werd niet behaald door eigen kracht of militaire genialiteit, maar door de opgeheven handen van Mozes, een beeld van aanhoudend gebed en Christus' onophoudelijke voorspraak. Als gedenkteken bouwde Mozes daar een altaar: "De HEERE is mijn Banier" (Jehova-Nissi).`,en:`**Archaeological and historical significance**
Rephidim's exact location is debated, but it was a crucial encampment in the Sinai Peninsula during the Israelites' exodus journey toward Mount Sinai.

**Cultural and geographical context**
It was a harsh, arid desert location where the Israelites found no water to drink, leading to severe murmuring and rebellion against Moses and God. It was also the site of the first unprovoked military attack on Israel by the Amalekites.

**Theological significance**
Rephidim stands as a profound testament to divine provision and intercession. God instructed Moses to strike the rock at Horeb, from which life-giving water flowed—a rock that the Apostle Paul identifies spiritually as Christ, who was struck for our salvation (1 Cor. 10:4). During the battle with Amalek, victory was secured only as long as Moses' hands were held up in prayer, illustrating the necessity of spiritual intercession in the warfare of faith.`},verses:["Exodus 17:1","Exodus 17:8","Numeri 33:14","1 Korinthe 10:4"],eras:[2]},{id:"rameses",coords:[30.79937,31.834217],name:{nl:"Pi-Rameses",en:"Pi-Ramesses"},region:{nl:"Egypte",en:"Egypt"},desc:{nl:"Startpunt van de Exodus.",en:"Starting point of the Exodus."},story:{nl:`**Archeologische en historische betekenis**
Rameses (of Pi-Ramesse) was een van de belangrijkste voorraadsteden die door de Israëlitische slaven voor de farao werd gebouwd. Archeologische opgravingen in de oostelijke Nijldelta hebben de restanten van deze enorme stad blootgelegd, wat de enorme bouwprojecten van Farao Ramses II bevestigt.

**Culturele en geografische context**
Gelegen in het vruchtbare land Gosen, was dit de plek waar de Israëlieten zich tijdens de hongersnood onder Jozef hadden gevestigd. Het fungeerde als het verzamelpunt voor de honderdduizenden Israëlieten op de nacht van de uittocht, net na de tiende plaag.

**Theologische betekenis**
Rameses staat symbool voor de ultieme onderdrukking door de wereld (Egypte) en het vertrekpunt van Gods verlossing. Het herinnert eraan dat God Zijn volk uitleidt uit het huis der dienstbaarheid om hen te brengen naar de beloofde rust.`,en:`**Archaeological and historical significance**
Rameses was a major store city built by the forced labor of the Israelite slaves. It is widely identified with Pi-Ramesses (Qantir), the grand capital built by Pharaoh Ramesses II in the fertile eastern Nile Delta.

**Cultural and geographical context**
Located in the land of Goshen, this region was given to Joseph's family centuries earlier because its rich pastureland was ideal for shepherds (an occupation despised by the Egyptians). Here, the Israelites multiplied greatly, transitioning from a small family clan into a mighty nation.

**Theological significance**
Rameses represents the house of bondage and the starting point of divine redemption. The Exodus began here on the morning after the first Passover. The preservation of the Israelites in Goshen during the plagues vividly demonstrated God's ability to distinguish and protect His chosen people amidst global judgment.`},verses:["Exodus 1:11","Exodus 12:37","Numeri 33:3"],eras:[2]},{id:"succoth",coords:[30.559,31.996],name:{nl:"Sukkoth",en:"Succoth"},region:{nl:"Egypte",en:"Egypt"},desc:{nl:"De eerste pleisterplaats na Rameses.",en:"The first encampment after Rameses."},story:{nl:`**Archeologische en historische betekenis**
Sukkoth was waarschijnlijk een Egyptische grensstad of militaire buitenpost aan de rand van de Wadi Tumilat. Historici geloven dat het diende als een verzamelplaats voor reizigers die Egypte verlieten of binnenkwamen.

**Culturele en geografische context**
De naam Sukkoth betekent "loofhutten" of "tenten". Het was de allereerste pleisterplaats voor de Israëlieten na hun haastige vertrek uit Rameses. Hier sloegen zij voor het eerst als een bevrijd volk, en niet als slaven, hun tenten op.

**Theologische betekenis**
Sukkoth herinnert theologisch aan de pelgrimsreis van de gelovige. God stelde later het Loofhuttenfeest (Sukkot) in om het volk er jaarlijks aan te herinneren dat Hij hen in hutten liet wonen toen Hij hen uit Egypte leidde (Leviticus 23:42-43).`,en:`**Archaeological and historical significance**
Succoth was likely an Egyptian border town or a military staging area just outside the main population centers of the Nile Delta. It served as the very first encampment for the Israelites after departing Rameses.

**Cultural and geographical context**
The name Succoth means "booths" or "tents," highlighting the sudden transition of the Israelites from settled slaves in stone cities to wandering pilgrims living in temporary shelters.

**Theological significance**
Succoth marks the definitive break from Egyptian slavery and the beginning of the wilderness journey. It is here that God instituted the command to commemorate the Exodus and consecrate the firstborn (Exodus 13). It symbolizes the believer's departure from the bondage of sin into a life of faith, dependent entirely on God's guidance, visibly manifested for the first time here as the pillar of cloud and fire.`},verses:["Exodus 12:37","Exodus 13:20","Numeri 33:5"],eras:[2]},{id:"etham",coords:[30.5475,31.963611],name:{nl:"Etham",en:"Etham"},region:{nl:"Woestijn",en:"Wilderness"},desc:{nl:"Aan de rand van de woestijn.",en:"On the edge of the wilderness."},story:{nl:`**Archeologische en historische betekenis**
Etham markeerde de uiterste grens van de bewoonde wereld aan de Egyptische grens, vlakbij de vestingwerken die Egypte beschermden tegen indringers uit de woestijn.

**Culturele en geografische context**
Etham lag "aan de rand van de woestijn". Vanaf hier betrad het volk de onherbergzame wildernis waar overleving zonder goddelijke ingreep onmogelijk was. Hierna beval God hen om te keren en te legeren vóór [Pi-Hachiroth](model:parting_sea:geography) en [Baäl-Zefon](model:parting_sea:geography), om Farao in de val te lokken.

**Theologische betekenis**
Bij Etham ging God voor het eerst expliciet voor hen uit in een wolkkolom overdag en een vuurkolom 's nachts. Dit benadrukt dat wanneer we de grens van de 'veilige' wereld passeren en de wildernis betreden, Gods zichtbare leiding en aanwezigheid ons leiden en beschermen.`,en:`**Archaeological and historical significance**
Etham marked the absolute edge of the inhabited world and the boundary of the Egyptian wilderness. Its exact location is lost, but it represented the point of no return for the fleeing Israelites.

**Cultural and geographical context**
Situated "on the edge of the wilderness," Etham was where the harsh, unforgiving desert truly began. Here, God commanded a seemingly illogical maneuver: to turn back and camp before [Pi-Hahiroth](model:parting_sea:geography) between [Migdol](model:parting_sea:floorPlan) and the sea, opposite [Baal-Zephon](model:parting_sea:geography).

**Theological significance**
At Etham, God commanded them to turn back, trapping themselves against the sea. This divine detour was purposefully designed to harden Pharaoh's heart and to create an inescapable crisis where Israel's only hope would be the miraculous deliverance of the Lord, proving that salvation is entirely of God.`},verses:["Exodus 13:20","Numeri 33:6"],eras:[2]},{id:"baal_zephon",coords:[30.860556,32.171389],name:{nl:"Baäl-Zefon",en:"Baal-Zephon"},region:{nl:"Egypte",en:"Egypt"},desc:{nl:"Plaats aan de overkant van Pi-Hachiroth.",en:"Place opposite Pi-Hahiroth."},story:{nl:`**Archeologische en historische betekenis**
Baäl-Zefon wordt geassocieerd met een heiligdom voor een Kanaänitische of Fenicische weergod (Baäl van het Noorden). Het diende waarschijnlijk als een baken voor zeevaarders nabij het huidige Suezkanaal of het Bardawil-meer.

**Culturele en geografische context**
God beval Israël om "om te keren" en zich te legeren tegenover Baäl-Zefon, direct aan de [Rode Zee](model:parting_sea:geography). Dit was een schijnbare valstrik: ze zaten klem tussen de zee, de wildernis en het Egyptische leger, vlak bij [Pi-Hachiroth](model:parting_sea:geography) en [Migdol](model:parting_sea:floorPlan).

**Theologische betekenis**
De keuze voor deze specifieke locatie was een goddelijke uitdaging. God toonde niet alleen Zijn heerschappij over Farao, maar ook dat de afgod Baäl-Zefon machteloos was. Hier spleet God de [Rode Zee](model:parting_sea:geography), wat Zijn absolute soevereiniteit bewijst.`,en:`**Archaeological & Historical Significance**
Baal-Zephon is associated with a sanctuary dedicated to a Canaanite or Egyptian deity, likely located near the northern end of the Gulf of Suez or the Bitter Lakes.

**Cultural & Geographical Context**
It was a prominent landmark near the Red Sea crossing. By commanding Israel to camp opposite a pagan shrine, the ensuing miracle served as a direct affront to the regional gods of Egypt, demonstrating their absolute powerlessness, right next to [Pi-Hahiroth](model:parting_sea:geography) and [Migdol](model:parting_sea:floorPlan).

**Theological Significance**
Trapped between the impassable sea, the mountains, and Pharaoh's advancing chariots at Baal-Zephon, Israel experienced the ultimate test of faith. The resulting parting of the [Red Sea](model:parting_sea:geography) stands as the eternal proof that God makes a way where there is no way.`},verses:["Exodus 14:2","Exodus 14:9","Numeri 33:7"],eras:[2]},{id:"pi_hahiroth",coords:[30.8333,32.25],name:{nl:"Pi-Hachiroth",en:"Pi-Hahiroth"},region:{nl:"Egypte (Rode Zee)",en:"Egypt (Red Sea)"},desc:{nl:"Legerplaats van Israël vóór de doortocht van de Rode Zee.",en:"Israel's encampment before the parting of the Red Sea."},story:{nl:`**Archeologische & Historische Betekenis**

Pi-Hachiroth (betekenis: 'monding van de kanalen' of 'plaats waar het riet groeit') was de laatste legerplaats van de Israëlieten in Egypte voordat zij door de Rode Zee trokken. De exacte locatie is onderwerp van debat, maar archeologische en topografische studies situeren het nabij de Bittermeren of de noordelijke Golf van Suez, direct aan de grens van de wildernis.

**Culturele & Geografische Context**

Onder leiding van de wolkkolom beval God het volk om om te keren en zich te legeren bij Pi-Hachiroth, ingesloten tussen [Migdol](model:parting_sea:floorPlan) (een Egyptische grensvesting) en de zee, recht tegenover [Baäl-Zefon](model:parting_sea:geography).

**Theologische Betekenis**

Pi-Hachiroth is de plek van de grote crisis: het volk zat hopeloos klem tussen de aanstormende Egyptische strijdwagens en de kolkende wateren van de [Rode Zee](model:parting_sea:geography). Hier riep Mozes het volk toe: "Vrees niet, sta vast en zie het heil van de HEERE". Het was de geboorteplaats van Israëls geloof en getuigt van Gods kracht om een weg te banen waar geen weg is.`,en:`**Archaeological & Historical Significance**

Pi-Hahiroth was the final camp of the fleeing Israelites in Egypt before the Red Sea crossing. It is located near the Bitter Lakes or northern Gulf of Suez.

**Cultural & Geographical Context**

God commanded Israel to encamp here, hemmed in between [Migdol](model:parting_sea:floorPlan) and the sea, opposite [Baal-Zephon](model:parting_sea:geography).

**Theological Significance**

This was the site of the ultimate crisis where Israel was trapped by Pharaoh's army, leading to the miraculous parting of the [Red Sea](model:parting_sea:geography).`},verses:["Exodus 14:2","Exodus 14:9","Numeri 33:7"],eras:[2]},{id:"migdol",coords:[30.9,32.18],name:{nl:"Migdol",en:"Migdol"},region:{nl:"Egypte (Grensgebied)",en:"Egypt (Border Region)"},desc:{nl:"Een Egyptische grensvesting en wachttoren nabij de Rode Zee.",en:"An Egyptian border fortress and watchtower near the Red Sea."},story:{nl:`**Archeologische & Historische Betekenis**

'Migdol' is het Hebreeuwse woord voor toren of vesting. Het verwijst naar een reeks Egyptische forten langs de oostgrens, die bedoeld waren om invallen uit de Sinaï te voorkomen. Archeologen hebben verschillende van deze forten opgegraven langs de oude wegen, uitgerust met dikke muren en wachttorens.

**Culturele & Geografische Context**

Toen Israël zich legerde tussen Migdol en de zee, bevonden zij zich in de schaduw van de Egyptische militaire macht. De vesting hield toezicht op de grens, wat betekende dat de ontsnapping van het volk direct werd gerapporteerd aan Farao, wat leidde tot zijn snelle achtervolging.\\n\\n**Theologische Betekenis**

Migdol staat symbool voor de schijnbare onmogelijkheid van Israëls ontsnapping: de menselijke forten hielden hen tegen, de wildernis sloot hen in. Maar de doortocht door de [Rode Zee](model:parting_sea:geography) bewees dat geen enkele menselijke vesting of leger stand kan houden tegen de bevrijdende macht van de HEERE.`,en:`**Archaeological & Historical Significance**

'Migdol' means tower or fortress, referring to the chain of Egyptian military outposts along the eastern border.

**Cultural & Geographical Context**

Israel camped in the shadow of this fortress, making their escape visible to the Egyptian military outposts.

**Theological Significance**

Migdol represents the human obstacles to Israel's escape, which were completely bypassed when God parted the [Red Sea](model:parting_sea:geography).`},verses:["Exodus 14:2","Numeri 33:7","Jeremia 44:1","Jeremia 46:14"],eras:[2,5]},{id:"marah",coords:[29.34604,32.94284],name:{nl:"Mara",en:"Marah"},region:{nl:"Sinaï",en:"Sinai"},desc:{nl:"Plaats van het bittere water.",en:"Place of bitter water."},story:{nl:`**Archeologische en historische betekenis**
Mara bevindt zich vermoedelijk bij Ain Hawarah, een bron op de route langs de oostkust van de Golf van Suez, die berucht is om zijn zware mineralen en bittere smaak.

**Culturele en geografische context**
Drie dagen lang hadden de Israëlieten door de gloeiend hete Sur-woestijn getrokken zonder water. Toen ze eindelijk water vonden, was het ondrinkbaar. De teleurstelling leidde tot het eerste grote gemurmureer tegen Mozes na de verlossing.

**Theologische betekenis**
God toonde Mozes een stuk hout ("boom") dat in het water geworpen moest worden, waardoor het zoet werd. Theologisch wijst dit hout vooruit naar het kruishout van Christus, dat de bitterheid van de zonde, het lijden en de dood transformeert tot levend en zoet water voor de gelovige. Hier openbaarde God Zich als "Jehova-Rapha" (De HEERE Uw Heelmeester).`,en:`**Archaeological and historical significance**
Marah is likely located at Ain Hawarah, a spring in the Sinai Peninsula known even today for its highly mineralized, bitter water that is unfit for human consumption.

**Cultural and geographical context**
After experiencing the euphoria of deliverance at the Red Sea, the Israelites marched for three agonizing days into the desert of Shur without finding water. When they finally found water at Marah, it was too bitter to drink, leading to immediate despair and grumbling.

**Theological significance**
Marah (meaning "Bitter") was a deliberate test of Israel's heart. God instructed Moses to throw a specific piece of wood into the water, which miraculously made it sweet. Theologically, this points to the cross of Christ (the wood/tree) which absorbs the bitterness of life and divine judgment, transforming the believer's bitter trials into the sweetness of grace and healing.`},verses:["Exodus 15:23","Numeri 33:8"],eras:[2]},{id:"elim",coords:[29.254722,32.915833],name:{nl:"Elim",en:"Elim"},region:{nl:"Sinaï",en:"Sinai"},desc:{nl:"Oase met 12 waterbronnen en 70 palmbomen.",en:"Oasis with 12 springs and 70 palm trees."},story:{nl:`**Archeologische en historische betekenis**
Elim wordt door vroege christelijke pelgrims en historici vaak geïdentificeerd met Wadi Gharandel, een plek die tot op de dag van vandaag bekend staat om zijn overvloedige zoetwaterbronnen en weelderige palmbomen.

**Culturele en geografische context**
Na de bittere ervaring bij Mara kwam het volk bij Elim, een ware woestijnoase. De twaalf waterbronnen en zeventig palmbomen boden fysiek herstel en schaduw aan de miljoenen Israëlieten.

**Theologische betekenis**
Elim is het bijbelse beeld van Gods voorbereide rust en overvloed na een periode van beproeving. De getallen (12 en 70) zijn niet toevallig: 12 verwijst naar de stammen van Israël en 70 naar het getal van de volkeren of de oudsten. Het symboliseert Gods volmaakte voorziening voor heel Zijn volk.`,en:`**Archaeological and historical significance**
Elim is often identified by early pilgrims with Wadi Garandel, a beautiful oasis located a short journey south of the bitter waters of Marah.

**Cultural and geographical context**
Unlike the harsh desert surrounding it, Elim was a lush sanctuary boasting twelve wells of fresh water and seventy palm trees, providing abundant shade and rest for the exhausted multitude.

**Theological significance**
Elim represents God's gracious provision and seasons of rest following periods of bitter testing. The specific numbers—twelve wells (corresponding to the twelve tribes of Israel) and seventy palm trees (corresponding to the seventy elders)—symbolize divine perfection, completeness, and God's abundant sufficiency for His covenant people during their earthly pilgrimage.`},verses:["Exodus 15:27","Numeri 33:9"],eras:[2]},{id:"ur",coords:[30.962222,46.104444],name:{nl:"Ur der Chaldeeën",en:"Ur of the Chaldeans"},region:{nl:"Mesopotamië",en:"Mesopotamia"},desc:{nl:"De geboorteplaats van Abraham.",en:"The birthplace of Abraham."},story:{nl:`**Archeologische en historische betekenis**
Ur der Chaldeeën (huidige Tell el-Muqayyar in Irak) was een van de machtigste en meest geavanceerde Sumerische stadstaten in het oude Mesopotamië. Opgravingen in de jaren 1920 toonden een hoogontwikkelde cultuur met monumentale ziggurats, wiskunde, en uitgebreide handel.

**Culturele en geografische context**
Ur was een rijk handelscentrum nabij de monding van de rivieren Eufraat en Tigris. De stad was diep doordrenkt van afgoderij, met name de aanbidding van de maangod Nanna (Sin). Terach, Abrahams vader, leefde midden in deze heidense context.

**Theologische betekenis**
Gods roeping van Abraham uit Ur toont Zijn soevereine genade: Hij koos een man uit een afgodisch bolwerk en riep hem om alles achter te laten (cultuur, zekerheid, en familie). Het versterkt het principe dat de roeping van de gelovige betekent dat men een pelgrim en vreemdeling op aarde wordt, op zoek naar de stad waarvan God de Bouwmeester is (Hebreeën 11).`,en:`**Archaeological and historical significance**
Ur of the Chaldeans (modern Tell el-Muqayyar in Iraq) was one of the most powerful and advanced Sumerian city-states in ancient Mesopotamia. Excavations in the 1920s revealed a highly developed culture with monumental ziggurats, advanced mathematics, and extensive trade.

**Cultural and geographical context**
Ur was a wealthy commercial hub near the mouth of the Euphrates and Tigris rivers. The city was deeply steeped in idolatry, specifically the worship of the moon god Nanna (Sin). Terah, Abraham's father, lived amidst this pagan context.

**Theological significance**
God's calling of Abraham out of Ur demonstrates His sovereign grace: He chose a man from an idolatrous stronghold and called him to leave everything behind (culture, security, and family). It reinforces the principle that the calling of the believer means becoming a pilgrim and stranger on earth, seeking the city whose architect and builder is God (Hebrews 11).`},verses:["Genesis 11:28","Genesis 11:31","Nehemia 9:7"],eras:[2]},{id:"haran",coords:[36.864444,39.032778],name:{nl:"Haran",en:"Haran"},region:{nl:"Mesopotamië",en:"Mesopotamia"},desc:{nl:"Waar Abraham verbleef voordat hij naar Kanaän ging.",en:"Where Abraham stayed before entering Canaan."},story:{nl:`**Archeologische en historische betekenis**
Haran was een prominente oude handelsstad in het noorden van Mesopotamië (huidig Turkije). Net als Ur was Haran een belangrijk centrum voor de verering van de maangod Sin.

**Culturele en geografische context**
Gelegen aan de belangrijke karavaanroutes tussen Ninevé en Damascus, was het een natuurlijke tussenstop voor Terach en Abraham. Toen Terach zich hier vestigde, pauzeerde de reis naar Kanaän totdat Terach op 205-jarige leeftijd stierf.

**Theologische betekenis**
Haran staat symbool voor het halve werk: de roeping werd gedeeltelijk beantwoord, maar de reis stagneerde door aardse of familiebanden. Pas na de dood van zijn vader verliet Abraham Haran definitief op 75-jarige leeftijd om volledig in gehoorzaamheid Kanaän binnen te trekken, wat de noodzaak van radicale toewijding illustreert.`,en:`**Archaeological and historical significance**
Haran was a prominent ancient commercial city in northern Mesopotamia (modern Turkey). Like Ur, Haran was a major center for the worship of the moon god Sin.

**Cultural and geographical context**
Situated on the vital caravan routes between Nineveh and Damascus, it was a natural stopping point for Terah and Abraham. When Terah settled here, the journey to Canaan paused until Terah died at the age of 205.

**Theological significance**
Haran symbolizes half-measures: the calling was partially answered, but the journey stagnated due to earthly or family ties. Only after the death of his father did Abraham definitively leave Haran at age 75 to step fully into obedience and enter Canaan, illustrating the necessity of radical devotion to God's call.`},verses:["Genesis 11:31","Genesis 12:4","Handelingen 7:2"],eras:[2]},{id:"beersheba",coords:[31.244722,34.840833],name:{nl:"Beër-Sjeba",en:"Beersheba"},region:{nl:"Kanaän",en:"Canaan"},desc:{nl:"Zuidelijke grens van Israël, put van de eed.",en:"Southern border of Israel, well of the oath."},story:{nl:`**Archeologische en historische betekenis**
Beër-Sjeba is de belangrijkste stad in de Negev-woestijn. Opgravingen bij Tel Beër-Sjeba hebben restanten onthuld van een versterkte Israëlitische stad met een geavanceerd watersysteem, wat essentieel was voor bewoning in dit droge gebied.

**Culturele en geografische context**
De naam betekent "Put van de Eed" of "Put van Zeven". Het markeerde de diepste zuidelijke grens van het vruchtbare land van Israël. Het bekende spreekwoord "van Dan tot Beër-Sjeba" werd in de Bijbel gebruikt om het gehele grondgebied van de natie aan te duiden.

**Theologische betekenis**
Beër-Sjeba was een heilige plaats voor de aartsvaders. Abraham sloot hier een vredesverbond met Abimelech, Izak ontving hier een verschijning van God en bouwde een altaar, en Jakob bracht hier offers voordat hij naar Egypte trok. Het is de plek van verbondsvernieuwing en de verzekering van Gods blijvende beloften aan het nageslacht.`,en:`**Archaeological and historical significance**
Beersheba is the most important city in the Negev desert. Excavations at Tel Beersheba have revealed remains of a fortified Israelite city with a sophisticated water system, essential for survival in this arid region.

**Cultural and geographical context**
The name means "Well of the Oath" or "Well of Seven." It marked the southernmost boundary of the fertile land of Israel. The famous idiom "from Dan to Beersheba" was used in the Bible to denote the entire territory of the nation.

**Theological significance**
Beersheba was a sacred site for the patriarchs. Abraham made a covenant of peace with Abimelech here, Isaac received a manifestation of God and built an altar, and Jacob offered sacrifices before journeying down to Egypt. It is a place of covenant renewal and the assurance of God's enduring promises to their offspring.`},verses:["Genesis 21:31","Genesis 26:33","Richteren 20:1"],eras:[2]},{id:"nineveh",coords:[36.3594,43.1528],name:{nl:"Ninevé",en:"Nineveh"},region:{nl:"Assyrië",en:"Assyria"},desc:{nl:"Hoofdstad van Assyrië, bezocht door Jona.",en:"Capital of Assyria, visited by Jonah."},story:{nl:`**Archeologische en historische betekenis**
Ninevé, gelegen aan de oostelijke oever van de Tigris in het huidige Irak, was een van de oudste en machtigste steden ter wereld en werd later de glorieuze hoofdstad van het wrede Assyrische rijk onder Sanherib.

**Culturele en geografische context**
In haar bloeitijd was Ninevé een metropool met enorme muren en paleizen. De Assyriërs stonden in de hele antieke wereld bekend om hun ongekende wreedheid en militaire terreur, wat verklaart waarom de profeet Jona weigerde hen tot bekering op te roepen.

**Theologische betekenis**
De stad vormt het decor voor een van de grootste theologische ommekeren in de Bijbel: het boek Jona. Het illustreert dat Gods ontzagwekkende genade zich uitstrekt tot over de grenzen van Israël, zelfs tot de meest verdorven en vijandige heidense naties, mits zij zich in zak en as bekeren. Uiteindelijk, toen de stad later weer in wreedheid verviel, werd zij conform de profetie van Nahum verwoest (612 v.Chr.).`,en:`**Archaeological and historical significance**
Nineveh, located on the eastern bank of the Tigris River in modern-day Iraq, was one of the oldest and most powerful cities in the world and later became the glorious capital of the brutal Assyrian Empire under Sennacherib.

**Cultural and geographical context**
In its prime, Nineveh was a massive metropolis with enormous walls and palaces. The Assyrians were notorious throughout the ancient world for their unprecedented cruelty and military terror, which explains why the prophet Jonah refused to call them to repentance.

**Theological significance**
The city forms the backdrop for one of the greatest theological turnarounds in the Bible: the book of Jonah. It illustrates that God's awe-inspiring grace extends beyond the borders of Israel, even to the most depraved and hostile pagan nations, provided they repent in sackcloth and ashes. Ultimately, when the city later reverted to cruelty, it was destroyed in fulfillment of Nahum's prophecy (612 BC).`},verses:["Genesis 10:11","Jona 1:2","Jona 3:2","Nahum 1:1"],eras:[4,7]},{id:"nazareth",coords:[32.70214,35.29769],name:{nl:"Nazareth",en:"Nazareth"},region:{nl:"Galilea",en:"Galilee"},desc:{nl:"De woonplaats van Jezus waar Hij opgroeide.",en:"The hometown where Jesus grew up."},story:{nl:`**Archeologische en historische betekenis**
Nazareth was in de eerste eeuw een onbeduidend, klein agrarisch dorpje in het heuvelland van Beneden-Galilea. Archeologisch materiaal uit de tijd van Jezus toont een nederzetting van hooguit enkele honderden bewoners, levend in grote armoede.

**Culturele en geografische context**
Nazareth lag in het noorden, ver weg van de theologische en politieke elite in Jeruzalem. De uitdrukking van Nathanaël, "Kan uit Nazareth iets goeds komen?" weerspiegelt het destijds heersende vooroordeel dat Galilea (en zeker Nazareth) geestelijk en cultureel inferieur was.

**Theologische betekenis**
Dit was de woonplaats waar de Zoon van God opgroeide ('de Nazarener'). Theologisch onderstreept Nazareth de vernedering en menswording van Christus. De Koning der koningen verkoos niet te groeien in een paleis in Jeruzalem, maar verbleef bijna dertig jaar in de obscuriteit van een eenvoudige timmermanswerkplaats. Het toont dat Gods majesteit zich vaak openbaart in wat voor de wereld veracht en gering is.`,en:`**Archaeological and historical significance**
Nazareth was an insignificant, small agricultural village in the hill country of Lower Galilee during the first century. Archaeological evidence from the time of Jesus shows a settlement of at most a few hundred inhabitants, living in deep poverty.

**Cultural and geographical context**
Nazareth was located in the north, far from the theological and political elite in Jerusalem. Nathanael's expression, "Can anything good come out of Nazareth?" reflects the prevailing prejudice of the time that Galilee (and certainly Nazareth) was spiritually and culturally inferior.

**Theological significance**
This was the hometown where the Son of God grew up ('the Nazarene'). Theologically, Nazareth underscores the humiliation and incarnation of Christ. The King of kings chose not to grow up in a palace in Jerusalem, but spent nearly thirty years in the obscurity of a simple carpenter's workshop. It demonstrates that God's majesty often reveals itself in what the world despises and considers lowly.`},verses:["Mattheüs 2:23","Lukas 1:26","Lukas 4:16","Johannes 1:46"],eras:[6]},{id:"capernaum",coords:[32.881111,35.575],name:{nl:"Kafarnaüm",en:"Capernaum"},region:{nl:"Galilea",en:"Galilee"},desc:{nl:"Het centrum van Jezus' bediening rondom het meer.",en:"The center of Jesus' ministry around the sea."},story:{nl:`**Archeologische en historische betekenis**
Kafarnaüm (Kfar Nachoem, "Dorp van Troost") was een welvarend vissersdorp aan de noordwestelijke oever van het Meer van Galilea. Opgravingen hebben indrukwekkende vondsten opgeleverd, waaronder een prachtige witte kalkstenen synagoge en het huis van Petrus.

**Culturele en geografische context**
Kafarnaüm lag aan de Via Maris, een grote internationale handelsroute. Er was een belastingkantoor (waar Mattheüs werd geroepen) en een Romeins garnizoen. Het meer was rijk aan vis, wat verklaart waarom veel van Jezus' discipelen lokale vissers waren.

**Theologische betekenis**
Nadat Jezus uit Nazareth werd verdreven, maakte Hij Kafarnaüm tot Zijn uitvalsbasis en het "hoofdkwartier" van Zijn Galileese bediening. Nergens ter wereld deed Jezus zoveel wonderen (genezingen, demonen uitdrijven, de prediking van het Brood des Levens) als hier. Ondanks dit grote licht weigerde de stad zich te bekeren, wat leidde tot Jezus' oordeel dat de stad tot in het dodenrijk zou worden neergestoten (Mattheüs 11:23).`,en:`**Archaeological and historical significance**
Capernaum (Kfar Nahum, "Village of Comfort") was a prosperous fishing village on the northwestern shore of the Sea of Galilee. Excavations have yielded impressive finds, including a beautiful white limestone synagogue and the house of Peter.

**Cultural and geographical context**
Capernaum was located on the Via Maris, a major international trade route. It had a tax office (where Matthew was called) and a Roman garrison. The sea was rich in fish, explaining why many of Jesus' disciples were local fishermen.

**Theological significance**
After being driven out of Nazareth, Jesus made Capernaum His home base and the "headquarters" of His Galilean ministry. Nowhere in the world did Jesus perform as many miracles (healings, casting out demons, preaching the Bread of Life) as here. Despite this great light, the city refused to repent, leading to Jesus' judgment that the city would be brought down to Hades (Matthew 11:23).`},verses:["Mattheüs 4:13","Markus 1:21","Lukas 4:31","Johannes 6:59"],eras:[6]},{id:"hebron",coords:[31.525087,35.10222],name:{nl:"Hebron",en:"Hebron"},region:{nl:"Juda",en:"Judah"},desc:{nl:"Rustplaats van Abraham, Isaäk en Jakob.",en:"Resting place of Abraham, Isaac, and Jacob."},story:{nl:`**Archeologische en historische betekenis**
Hebron, gelegen op ruim 900 meter hoogte in het Judese heuvelland, is een van de oudste continu bewoonde steden ter wereld. Koning Herodes bouwde later een kolossaal heiligdom over de Machpela-grot, welk gebouw er vandaag nog steeds staat.

**Culturele en geografische context**
Hebron was een vruchtbaar gebied vol wijngaarden (Dal van Eskol). Abraham kocht hier van Efron de Hethiet een akker en een spelonk als familiebegraafplaats. Hier liggen Abraham en Sara, Izak en Rebekka, en Jakob en Lea begraven.

**Theologische betekenis**
Hebron ("Vriendschap" of "Verbondschap") is theologisch de plek van diep gewortelde verbondstrouw. Abraham kreeg de belofte van het land en ontving dit kleine stukje als een onderpand. Eeuwen later werd David in Hebron door God geleid om eerst over Juda (voor 7,5 jaar) en later over heel Israël tot koning te worden gezalfd. Het is de bodem waaruit het messiaanse koningschap ontkiemde.`,en:`**Archaeological and historical significance**
Hebron, located at over 900 meters altitude in the Judean hill country, is one of the oldest continuously inhabited cities in the world. King Herod later built a colossal sanctuary over the Cave of Machpelah, a building that still stands today.

**Cultural and geographical context**
Hebron was a fertile area full of vineyards (Valley of Eshcol). Abraham bought a field and a cave from Ephron the Hittite here as a family burial ground. Abraham and Sarah, Isaac and Rebekah, and Jacob and Leah are buried here.

**Theological significance**
Hebron ("Friendship" or "Alliance") is theologically the place of deeply rooted covenant faithfulness. Abraham received the promise of the land and received this small piece as a down payment. Centuries later, David was guided by God to be anointed king in Hebron, first over Judah (for 7.5 years) and later over all Israel. It is the soil from which the messianic kingship sprouted.`},verses:["Genesis 13:18","Genesis 23:2","2 Samuël 2:1","2 Samuël 5:3"],eras:[2,4,7]},{id:"sodom",coords:[31.20849,35.449223],name:{nl:"Sodom en Gomorra",en:"Sodom and Gomorrah"},region:{nl:"Vlakte van de Jordaan",en:"Plain of the Jordan"},desc:{nl:"Verwoest door vuur en zwavel vanwege hun zonde.",en:"Destroyed by fire and brimstone due to their sin."},story:{nl:`**Archeologische en historische betekenis**
Hoewel de exacte locatie vaak debatteerd wordt, plaatsen veel historici en archeologen de steden van de vlakte onder of nabij de ondiepe zuidelijke wateren van de huidige Dode Zee.

**Culturele en geografische context**
De steden Sodom en Gomorra lagen in een vruchtbare vallei, die in de dagen van Abraham "waterrijk was als de hof des Heeren" (Genesis 13:10). Lot koos ervoor hier zijn tenten op te slaan vanwege de rijkdom van het land, hoewel de mannen van Sodom zeer slecht waren.

**Theologische betekenis**
Vanwege de hemeltergende en onbekeerlijke verdorvenheid liet de Heere vuur en zwavel regenen op deze steden. Sodom en Gomorra dienen in de hele Schrift als een waarschuwingsbeeld van Gods heilige toorn en Zijn onafwendbare eindgericht over de zonde, en als contrast voor de reddende genade die Lot uit het verderf trok.`,en:`**Archaeological and historical significance**
The exact location is debated...`},verses:["Genesis 13:10","Genesis 19:24","Lukas 17:29","Judas 1:7"],eras:[2]},{id:"bethlehem",coords:[31.704306,35.207639],name:{nl:"Bethlehem",en:"Bethlehem"},region:{nl:"Juda",en:"Judah"},desc:{nl:"Geboorteplaats van koning David en de Heere Jezus.",en:"Birthplace of King David and the Lord Jesus."},story:{nl:`**Archeologische en historische betekenis**
Bethlehem (Huis van het Brood) is een kleine, eeuwenoude stad in het bergland van Juda, zo'n tien kilometer ten zuiden van Jeruzalem.

**Culturele en geografische context**
Eerder heette het Efratha; in haar nabijheid werd Rachel begraven. In de velden van Bethlehem las de Moabitische Ruth aren op het land van Boaz. Later werd hier David, de herdersjongen en achterkleinzoon van Ruth, geboren en door Samuël tot koning gezalfd.

**Theologische betekenis**
De profeet Micha profeteerde dat uit deze ogenschijnlijk onbeduidende stad de Heerser van Israël zou voortkomen, Wiens uitgangen zijn van ouds, van de dagen der eeuwigheid (Micha 5:1). Dit werd heerlijk vervuld toen God in het vlees kwam en Jezus Christus, het ware Brood des levens, in Bethlehem in een kribbe werd geboren om Zijn volk te verlossen.`,en:`**Archaeological and historical significance**
Bethlehem (House of Bread) is a small ancient town...`},verses:["Genesis 35:19","Ruth 4:11","1 Samuël 16:1","Micha 5:1","Lukas 2:4"],eras:[4,6,7]},{id:"mount_sinai",coords:[28.539722,33.973333],name:{nl:"De Berg Sinaï (Horeb)",en:"Mount Sinai (Horeb)"},region:{nl:"Sinaïwoestijn",en:"Sinai Desert"},desc:{nl:"De berg waar God de wet aan Mozes gaf.",en:"The mountain where God gave the Law to Moses."},story:{nl:`**Archeologische en historische betekenis**
De berg Sinaï (vaak geïdentificeerd met Jebel Musa in het zuiden van het Sinaï-schiereiland) is de formidabele granieten berg in de wildernis waar het volk Israël maandenlang verbleef na de uittocht uit Egypte.

**Culturele en geografische context**
Het is een dor en woest gebied, ook Horeb genoemd ("De berg Gods"). Hier verscheen de Heere voor het eerst aan Mozes in de brandende doornstruik die niet verteerde.

**Theologische betekenis**
Theologisch markeert Sinaï het moment waarop het Oude Verbond werd gesloten. Onder donder, bliksem, dikke rook en bazuingeschal daalde de Heere Zelf neer in vuur en openbaarde Zijn absolute, onkreukbare heiligheid. Hij gaf de Tien Geboden en de gedetailleerde blauwdrukken voor de tabernakel en het priesterschap. Het toont de majesteit van Gods wet, die door haar strengheid (waar de berg niet eens aangeraakt mocht worden) het volk deed uitzien naar de genade die in Christus zou komen.`,en:`**Archaeological and historical significance**
Mount Sinai is the formidable granite mountain...`},verses:["Exodus 3:1","Exodus 19:18","Deuteronomium 4:11","Hebreeën 12:18"],eras:[2]},{id:"babylon",coords:[32.543333,44.422222],name:{nl:"Babel (Babylon)",en:"Babylon"},region:{nl:"Mesopotamië",en:"Mesopotamia"},desc:{nl:"Zinnebeeld van de wereld, plaats van ballingschap.",en:"Symbol of the world, place of exile."},story:{nl:`**Archeologische en historische betekenis**
Babel, gebouwd langs de Eufraat, vindt haar vroegste oorsprong bij de torenbouw in Sinear (Gen. 11). Eeuwen later bouwde koning Nebukadnezar het uit tot de absolute grootmacht en prachtstad van het Nabije Oosten, compleet met gigantische muren en hangende tuinen.

**Culturele en geografische context**
Toen Juda hardnekkig Gods wetten bleef overtreden, gebruikte God Babylon als een 'gouden beker in Zijn hand' om Zijn oordeel te voltrekken. In 586 v.Chr. verwoestte Nebukadnezar Jeruzalem en de Tempel, en voerde hij het volk Juda als ballingen mee naar Babylon.

**Theologische betekenis**
Babylon is in de theologie het ultieme, profetische archetype van de heidense, hoogmoedige mens die zich tegen God verheft. Waar Jeruzalem de stad van God is, vertegenwoordigt Babylon de goddeloze wereld. De Psalmen getuigen van het verdriet van het volk: "Aan de rivieren van Babel, daar zaten wij, ook weenden wij" (Ps. 137). Uiteindelijk profeteert Openbaring over de definitieve en vernietigende ondergang van het geestelijke Babylon.`,en:`**Archaeological and historical significance**
Babylon finds its earliest roots in the tower of Shinar...`},verses:["Genesis 11:9","2 Koningen 25:1","Psalm 137:1","Openbaring 18:2"],eras:[1,5]},{id:"sea_of_galilee",coords:[32.818906,35.590033],name:{nl:"Meer van Galilea",en:"Sea of Galilee"},region:{nl:"Galilea",en:"Galilee"},desc:{nl:"Het toneel van vele wonderen van Jezus.",en:"The scene of many miracles by Jesus."},story:{nl:`**Archeologische en historische betekenis**
Het Meer van Galilea (ook wel Meer van Tiberias of Meer Gennesareth) is een groot zoetwatermeer in het noorden van Israël, gelegen op ruim 200 meter onder zeeniveau. In de oudheid werd het omringd door bloeiende visserijsteden.

**Culturele en geografische context**
Vanwege de unieke ligging in de vallei is het meer berucht om plotselinge, zeer zware en levensgevaarlijke stormen die vanaf de omliggende heuvels neerstorten.

**Theologische betekenis**
Dit meer is het kloppend hart van Jezus' bediening. Hier riep Hij Zijn eerste discipelen (vissers) om vissers van mensen te worden. Op dit water wandelde Hij in de nacht, en met één enkel machtswoord ("Zwijg, wees stil!") kalmeerde Hij de elementen, wat Zijn goddelijke heerschappij over de schepping demonstreert. Ook na Zijn opstanding verscheen Hij hier aan Zijn discipelen bij de wonderbaarlijke visvangst.`,en:`**Archaeological and historical significance**
The Sea of Galilee (also known as the Sea of Tiberias or Lake Gennesaret) is a large freshwater lake in northern Israel, situated over 200 meters below sea level. In ancient times, it was surrounded by thriving fishing towns.

**Cultural and geographical context**
Due to its unique position in the valley, the lake is notorious for sudden, very severe and life-threatening storms that sweep down from the surrounding hills.

**Theological significance**
This lake is the beating heart of Jesus' ministry. Here He called His first disciples (fishermen) to become fishers of men. He walked on this water in the dead of night, and with a single word of power ("Peace, be still!"), He calmed the raging elements, demonstrating His divine lordship over creation. After His resurrection, He also appeared here to His disciples during the miraculous catch of fish.`},verses:["Mattheüs 4:18","Markus 4:39","Mattheüs 14:25","Johannes 21:1"],eras:[6]},{id:"jordan_river",coords:[31.761389,35.558333],name:{nl:"Rivier de Jordaan",en:"Jordan River"},region:{nl:"Kanaän",en:"Canaan"},desc:{nl:"De grensrivier en plaats van Jezus' doop.",en:"The border river and place of Jesus' baptism."},story:{nl:`**Archeologische en historische betekenis**
De Jordaan is de belangrijkste rivier in de regio. Hij stroomt vanuit de berg Hermon, door het Meer van Galilea, diep door de Riftvallei naar het laagste punt op aarde: de Dode Zee.

**Culturele en geografische context**
De rivier vormde een zware natuurlijke grens voor iedereen die vanuit het oosten het Beloofde Land wilde binnentrekken.

**Theologische betekenis**
De Jordaan staat in de Bijbel symbool voor overgang en geestelijke doorbraak. Jozua leidde het volk dwars door het wonderbaarlijk drooggevallen rivierbed het Beloofde Land in. Eeuwen later preekte Johannes de Doper hier een doop van bekering. De theologische climax vond plaats toen Jezus Zelf in dit water werd gedoopt, de hemel scheurde en de Drie-eenheid zich onthulde: de stem van de Vader, de Zoon in het water, en de Geest als een duif.`,en:`**Archaeological and historical significance**
The Jordan is the most important river in the region. It flows from Mount Hermon, through the Sea of Galilee, deep down the Rift Valley to the lowest point on earth: the Dead Sea.

**Cultural and geographical context**
The river formed a formidable natural border for anyone seeking to enter the Promised Land from the east.

**Theological significance**
In the Bible, the Jordan is a symbol of transition and spiritual breakthrough. Joshua led the people right through the miraculously dried riverbed into the Promised Land. Centuries later, John the Baptist preached a baptism of repentance here. The theological climax occurred when Jesus Himself was baptized in this water; the heavens tore open and the Trinity was revealed: the voice of the Father, the Son in the water, and the Spirit descending like a dove.`},verses:["Jozua 3:17","2 Koningen 5:14","Mattheüs 3:13","Markus 1:9"],eras:[3,6]},{id:"damascus",coords:[33.511112,36.30639],name:{nl:"Damascus",en:"Damascus"},region:{nl:"Syrië",en:"Syria"},desc:{nl:"Plaats van Paulus' radicale bekering.",en:"Place of Paul's radical conversion."},story:{nl:`**Archeologische en historische betekenis**
Damascus is een van de oudste continu bewoonde steden ter wereld, gelegen in een oase die gevoed wordt door de rivier Barada. In de Romeinse tijd was het een zeer welvarende en cruciale handelsstad (Decapolis-regio).

**Culturele en geografische context**
Gelegen ten noorden van Israël, herbergde de stad een aanzienlijke Joodse populatie met meerdere synagogen. Na de marteldood van Stefanus vluchtten veel christenen hierheen.

**Theologische betekenis**
Damascus is de plek van misschien wel de meest onverwachte en theologische invloedrijke bekering uit de wereldgeschiedenis. Saulus van Tarsus, ademend van dreiging en moord tegen de kerk, werd net buiten de stadspoorten verblind door het hemelse licht van de verheerlijkte Christus. Van de felste vervolger werd hij de grootste zendeling (de apostel Paulus). Dit illustreert de absolute en onweerstaanbare soevereiniteit van Gods reddende genade.`,en:`**Archaeological and historical significance**
Damascus is one of the oldest continuously inhabited cities in the world, situated in an oasis fed by the Barada River. During the Roman era, it was a highly prosperous and crucial commercial center.

**Cultural and geographical context**
Located north of Israel, the city housed a significant Jewish population with multiple synagogues. After the martyrdom of Stephen, many Christians fled here.

**Theological significance**
Damascus is the site of perhaps the most unexpected and theologically influential conversion in world history. Saul of Tarsus, breathing threats and murder against the church, was blinded just outside the city gates by the heavenly light of the glorified Christ. From the fiercest persecutor, he was transformed into the greatest missionary (the Apostle Paul). This powerfully illustrates the absolute and irresistible sovereignty of God's saving grace.`},verses:["Genesis 15:2","Handelingen 9:3","Handelingen 22:6","Galaten 1:17"],eras:[4,7]},{id:"antioch",coords:[36.226691,36.171743],name:{nl:"Antiochië",en:"Antioch"},region:{nl:"Syrië",en:"Syria"},desc:{nl:"Waar volgelingen voor het eerst Christenen werden genoemd.",en:"Where followers were first called Christians."},story:{nl:`**Archeologische en historische betekenis**
Antiochië aan de Orontes was na Rome en Alexandrië de derde grootste en belangrijkste metropool van het Romeinse Rijk. Het was een knooppunt van handel, cultuur en diverse filosofieën.

**Culturele en geografische context**
De stad kende een bruisende smeltkroes van culturen. Tot op dat moment werd het evangelie voornamelijk aan Joden verkondigd, maar in Antiochië braken Hellenistische (Griekse) gelovigen door die barrière en plantten de eerste grote, multiculturele gemeente.

**Theologische betekenis**
Antiochië is theologically het bruggenhoofd voor de wereldwijde zending. Hier werden de discipelen voor het allereerst "Christenen" genoemd (Hand. 11:26). De gemeente van Antiochië zond, onder leiding van de Heilige Geest, Paulus en Barnabas uit op hun baanbrekende zendingsreizen naar de heidense wereld. Het representeert de overgang van een lokale Joodse beweging naar een universele, wereldwijde Kerk.`,en:`**Archaeological and historical significance**
Antioch on the Orontes was the third largest and most important metropolis of the Roman Empire, after Rome and Alexandria. It was a major hub of commerce, culture, and diverse philosophies.

**Cultural and geographical context**
The city was a vibrant melting pot of cultures. Until that point, the gospel had primarily been preached to Jews, but in Antioch, Hellenistic (Greek) believers broke through that barrier and planted the first major multicultural church.

**Theological significance**
Theologically, Antioch is the bridgehead for global missions. It was here that the disciples were first called "Christians" (Acts 11:26). Driven by the Holy Spirit, the church of Antioch commissioned and sent out Paul and Barnabas on their groundbreaking missionary journeys to the Gentile world. It represents the crucial transition of Christianity from a localized Jewish movement to a universal, worldwide Church.`},verses:["Handelingen 11:26","Handelingen 13:1","Galaten 2:11"],eras:[6]},{id:"rome",coords:[41.8922,12.4852],name:{nl:"Rome",en:"Rome"},region:{nl:"Italië",en:"Italy"},desc:{nl:"Hoofdstad van het Rijk, bloedbad der martelaren.",en:"Capital of the Empire, bloodshed of martyrs."},story:{nl:`**Archeologische en historische betekenis**
Rome, de Stad op de Zeven Heuvelen, was het kloppend hart en de onbetwiste supermacht van de antieke wereld. Keizerlijke fora, het Colosseum en machtige tempels domineerden de horizon.

**Culturele en geografische context**
Als hoofdstad trok het mensen van over de hele bekende wereld. Ondanks wrede vervolgingen door keizers als Nero, die christenen als levende fakkels gebruikte, groeide de ondergrondse huisgemeente in Rome exponentieel.

**Theologische betekenis**
Rome is de climax van het boek Handelingen. Paulus schreef zijn absolute theologische meesterwerk (de Romeinenbrief) aan deze gemeente. Paulus (als staatsburger onthoofd) en Petrus (ondersteboven gekruisigd) stierven hier allebei de marteldood voor hun Verlosser. Het toont hoe het Koninkrijk van God onstuitbaar is: het kruipt uit de catacomben en overwint uiteindelijk zelfs het bloeddorstige hart van het Romeinse rijk door het bloed van het Lam.`,en:`**Archaeological and historical significance**
Rome, the City on Seven Hills, was the beating heart and undisputed superpower of the ancient world. Imperial forums, the Colosseum, and mighty temples dominated its skyline.

**Cultural and geographical context**
As the capital, it attracted people from all over the known world. Despite horrific persecutions by emperors like Nero, who used Christians as living torches, the underground house churches in Rome grew exponentially.

**Theological significance**
Rome serves as the dramatic climax to the book of Acts. Paul wrote his absolute theological masterpiece (the Epistle to the Romans) to this church. Both Paul (beheaded as a citizen) and Peter (crucified upside down) died their martyr's death for their Savior here. It stands as the ultimate proof that the Kingdom of God is unstoppable: creeping out from the catacombs, it ultimately conquered even the bloodthirsty heart of the Roman Empire through the blood of the Lamb.`},verses:["Handelingen 28:14","Romeinen 1:7","Romeinen 1:15","2 Timotheüs 1:17"],eras:[6]},{id:"sichem",name:{nl:"Sichem",en:"Shechem"},region:{nl:"Kanaän",en:"Canaan"},coords:[32.213611,35.281944],eras:[2,4,7],desc:{nl:"De plek waar God aan Abraham het land beloofde en waar hij zijn eerste altaar bouwde.",en:"The place where God promised the land to Abraham and where he built his first altar."},story:{nl:"Toen Abraham in Kanaän aankwam, was Sichem zijn eerste rustplaats. Hier verscheen de HEER aan hem en zei: 'Aan jouw nageslacht zal Ik dit land geven'. Abraham bouwde er direct een altaar (Gen 12:6-7). Later kocht Jakob hier een stuk land, en de botten van Jozef werden hier uiteindelijk begraven (Jozua 24:32). Nadat Salomo stierf, werd het koninkrijk Israël in Sichem in tweeën gescheurd, waarna het kort diende als de eerste hoofdstad van het noordelijke rijk.",en:"When Abraham arrived in Canaan, Shechem was his first resting place. Here the LORD appeared to him and said, 'To your offspring I will give this land'. Abraham immediately built an altar there (Gen 12:6-7). Later, Jacob bought a plot of land here, and the bones of Joseph were eventually buried here (Joshua 24:32). After Solomon's death, the kingdom of Israel was divided in Shechem, and it briefly served as the first capital of the northern kingdom."}},{id:"bethel",name:{nl:"Bethel",en:"Bethel"},region:{nl:"Kanaän",en:"Canaan"},coords:[31.922778,35.241389],eras:[2],desc:{nl:"Huis van God; de plek waar Jakob droomde over de ladder naar de hemel.",en:"House of God; the place where Jacob dreamed of the stairway to heaven."},story:{nl:"Op de vlucht voor zijn broer Esau, overnachtte Jakob in de open lucht met een steen als kussen. Hij droomde van een ladder die tot in de hemel reikte, met engelen die op en neer gingen. God beloofde hem daar Zijn zegen. Toen Jakob wakker werd, noemde hij de plek Bethel ('Huis van God') (Gen 28). Eeuwen later, toen het rijk scheurde, plaatste koning Jerobeam hier echter een gouden kalf, wat Bethel een centrum van afgoderij maakte.",en:"Fleeing from his brother Esau, Jacob slept outdoors with a stone for a pillow. He dreamed of a ladder reaching to heaven, with angels ascending and descending. God promised him His blessing there. When Jacob awoke, he named the place Bethel ('House of God') (Gen 28). Centuries later, when the kingdom split, King Jeroboam placed a golden calf here, making Bethel a center of idolatry."}},{id:"pniel",name:{nl:"Pniël",en:"Peniel"},region:{nl:"Gilead",en:"Gilead"},coords:[32.186,35.632],eras:[2],desc:{nl:"De doorwaadbare plaats aan de Jabbok waar Jakob worstelde met God.",en:"The ford of the Jabbok where Jacob wrestled with God."},story:{nl:"Vlak voordat Jakob na jarenlange ballingschap zijn broer Esau weer zou ontmoeten, bleef hij alleen achter bij de rivier de Jabbok. Een onbekende Man worstelde daar de hele nacht met hem. Jakob liet de Man niet los totdat hij hem zegende. De Man veranderde Jakobs naam in Israël ('hij worstelt met God'). Jakob noemde de plaats Pniël ('Gezicht van God'), want, zei hij, 'ik heb God van aangezicht tot aangezicht gezien en ik heb het overleefd' (Gen 32).",en:"Just before Jacob was to meet his brother Esau after years of exile, he stayed alone at the Jabbok River. An unknown Man wrestled with him there all night. Jacob refused to let the Man go unless He blessed him. The Man changed Jacob's name to Israel ('he struggles with God'). Jacob named the place Peniel ('Face of God'), saying, 'It is because I saw God face to face, and yet my life was spared' (Gen 32)."}},{id:"goshen",name:{nl:"Gosjen",en:"Goshen"},region:{nl:"Egypte",en:"Egypt"},coords:[30.65,31.75],eras:[2,3],desc:{nl:"De vruchtbare regio in Egypte waar de Israëlieten eeuwenlang woonden en vermenigvuldigden.",en:"The fertile region in Egypt where the Israelites lived and multiplied for centuries."},story:{nl:"Tijdens een wereldwijde hongersnood nodigde Jozef, destijds onderkoning van Egypte, zijn vader Jakob en zijn broers uit om in Egypte te komen wonen. De farao wees hen de regio Gosjen toe, het beste deel van het land in de Nijldelta. Hier leefden zij als schaapherdrs en groeiden uit tot een enorm volk (Gen 47). Toen God later de tien plagen over Egypte bracht, bleef Gosjen vaak gespaard, als bewijs dat God Zijn eigen volk afzonderde en beschermde (Exodus 8:22).",en:"During a global famine, Joseph, then vizier of Egypt, invited his father Jacob and his brothers to live in Egypt. The pharaoh assigned them the region of Goshen, the best part of the land in the Nile delta. Here they lived as shepherds and grew into an enormous nation (Gen 47). When God later brought the ten plagues upon Egypt, Goshen was often spared, demonstrating that God set apart and protected His own people (Exodus 8:22)."}},{id:"kadesh_barnea",name:{nl:"Kades-Barnea",en:"Kadesh-barnea"},region:{nl:"Woestijn Paran",en:"Wilderness of Paran"},coords:[30.648333,34.422222],eras:[2],desc:{nl:"De oase waar de twaalf verspieders terugkeerden en Israël weigerde Kanaän in te trekken.",en:"The oasis where the twelve spies returned and Israel refused to enter Canaan."},story:{nl:"Kades-Barnea was een enorm belangrijke locatie tijdens de Exodus. Vanaf hier stuurde Mozes twaalf verspieders om het Beloofde Land te verkennen. Tien kwamen terug met een ontmoedigend rapport over reuzen en onneembare steden. Alleen Jozua en Kaleb vertrouwden op God. Omdat het volk in opstand kwam en weigerde het land binnen te trekken, veroordeelde God hen tot 40 jaar zwerven in de woestijn. Kades bleef in die tijd lange tijd hun basiskamp (Numeri 13-14).",en:"Kadesh-barnea was a hugely important location during the Exodus. From here Moses sent twelve spies to explore the Promised Land. Ten returned with a discouraging report about giants and impregnable cities. Only Joshua and Caleb trusted God. Because the people rebelled and refused to enter the land, God condemned them to 40 years of wandering in the wilderness. Kadesh remained their base camp for a long time during those years (Numbers 13-14)."}},{id:"gilgal",name:{nl:"Gilgal",en:"Gilgal"},region:{nl:"Kanaän",en:"Canaan"},coords:[31.881883,35.459969],eras:[3],desc:{nl:"Het eerste basiskamp van Jozua na het wonderbaarlijk oversteken van de rivier de Jordaan.",en:"Joshua's first base camp after miraculously crossing the Jordan River."},story:{nl:"Na 40 jaar in de woestijn trok een nieuwe generatie Israëlieten eindelijk het Beloofde Land binnen door de Jordaan, die door God werd drooggelegd. Ze sloegen direct hun kamp op in Gilgal. Hier richtte Jozua een monument op van twaalf stenen uit het midden van de rivier, als blijvende herinnering. Ook werden hier alle mannen besneden (de schande van Egypte werd 'afgewenteld') en vierden ze voor het eerst in Kanaän het Pascha (Jozua 4-5).",en:"After 40 years in the desert, a new generation of Israelites finally entered the Promised Land through the Jordan River, which was dried up by God. They immediately set up camp in Gilgal. Here Joshua set up a monument of twelve stones taken from the middle of the river as a lasting memorial. All the men were also circumcised here (the reproach of Egypt was 'rolled away') and they celebrated the Passover for the first time in Canaan (Joshua 4-5)."}},{id:"ai",name:{nl:"Ai",en:"Ai"},region:{nl:"Kanaän",en:"Canaan"},coords:[31.916944,35.261111],eras:[3],desc:{nl:"De kleine stad waar Israël een dramatische nederlaag leed vanwege de zonde van Achan.",en:"The small city where Israel suffered a dramatic defeat due to Achan's sin."},story:{nl:"Na de miraculeuze overwinning op het machtige Jericho, leek de kleine stad Ai een makkelijke prooi. Maar Israëls aanval liep uit op een pijnlijke en dodelijke nederlaag. De reden was dat een man genaamd Achan heimelijk spullen uit Jericho had buitgemaakt, wat streng verboden was. Pas nadat de zonde werd blootgelegd en weggedaan, hielp God Jozua om Ai via een slimme hinderlaag alsnog in te nemen (Jozua 7-8).",en:"After the miraculous victory over the mighty Jericho, the small city of Ai seemed an easy target. But Israel's attack resulted in a painful and deadly defeat. The reason was that a man named Achan had secretly taken plunder from Jericho, which was strictly forbidden. Only after the sin was exposed and dealt with, did God help Joshua take Ai through a clever ambush (Joshua 7-8)."}},{id:"samaria",name:{nl:"Samaria",en:"Samaria"},region:{nl:"Israël (Noord)",en:"Israel (North)"},coords:[32.276111,35.195],eras:[4,7],desc:{nl:"De machtige maar vaak goddeloze hoofdstad van het Noordelijke tienstammenrijk Israël.",en:"The powerful but often godless capital of the Northern ten-tribe kingdom of Israel."},story:{nl:"Nadat het koninkrijk onder Salomo's zoon uiteenviel, werd Samaria uiteindelijk gebouwd als de hoofdstad van het noordelijke rijk (Israël) door koning Omri. Zijn zoon, de beruchte koning Achab, bouwde er een tempel voor Baäl samen met zijn Fenicische vrouw Izebel (1 Koningen 16). Samaria was een rijke, sterk gefortificeerde stad die door profeten als Amos en Hosea hevig werd bekritiseerd vanwege haar afgoderij en sociale onrecht. In 722 v.Chr. werd de stad verwoest door de Assyriërs.",en:"After the kingdom split under Solomon's son, Samaria was eventually built as the capital of the northern kingdom (Israel) by King Omri. His son, the infamous King Ahab, built a temple for Baal there with his Phoenician wife Jezebel (1 Kings 16). Samaria was a wealthy, highly fortified city that was heavily criticized by prophets like Amos and Hosea for its idolatry and social injustice. In 722 BC, the city was destroyed by the Assyrians."}},{id:"carmel",name:{nl:"Karmelberg",en:"Mount Carmel"},region:{nl:"Israël",en:"Israel"},coords:[32.6725,35.023333],eras:[4],desc:{nl:"De bergketen waar de profeet Elia de beslissende vuurproef aanging tegen de Baäl-priesters.",en:"The mountain range where the prophet Elijah had the decisive showdown by fire against the prophets of Baal."},story:{nl:"Toen koning Achab en Izebel het land hadden overspoeld met afgoderij en droogte, daagde de profeet Elia 450 priesters van Baäl uit op de Karmelberg. Wie met vuur uit de hemel op een altaar zou antwoorden, is de ware God. De Baäl-priesters schreeuwden een halve dag, maar er gebeurde niets. Daarna bad Elia één kort gebed, en vuur van de HERE verteerde niet alleen zijn offer, maar zelfs de stenen en het water in de greppel. Het volk viel op zijn gezicht en riep: 'De HERE is God!' (1 Koningen 18).",en:"When King Ahab and Jezebel had flooded the land with idolatry and drought, the prophet Elijah challenged 450 prophets of Baal on Mount Carmel. The God who answered by fire from heaven on an altar would be the true God. The Baal prophets shouted for half a day, but nothing happened. Then Elijah prayed one short prayer, and fire from the LORD consumed not only his sacrifice, but even the stones and the water in the trench. The people fell prostrate and cried: 'The LORD, He is God!' (1 Kings 18)."}},{id:"megiddo",name:{nl:"Megiddo",en:"Megiddo"},region:{nl:"Israël",en:"Israel"},coords:[32.585278,35.184444],eras:[4,8],desc:{nl:"Een uiterst strategische vestingstad; de Hebreeuwse naam (Har-Megiddo) leidde tot het woord 'Armageddon'.",en:"An extremely strategic fortress city; its Hebrew name (Har-Megiddo) led to the word 'Armageddon'."},story:{nl:"Megiddo lag op het belangrijkste kruispunt van internationale handelsroutes in de antieke wereld. Wie Megiddo had, beheerste de vallei. Salomo bouwde het uit tot een indrukwekkende vestingstad en stalde er zijn strijdwagens (1 Koningen 9:15). Vele bloedige veldslagen werden hier uitgevochten, waaronder die waarbij de goede koning Josia tragisch sneuvelde. Vanwege dit verleden van beslissende oorlogen, gebruikt het boek Openbaring de naam Harmagedon (Berg Megiddo) als symbool voor de eindstrijd (Openbaring 16:16).",en:"Megiddo was located at the most important crossroads of international trade routes in the ancient world. Whoever held Megiddo controlled the valley. Solomon expanded it into an impressive fortress city and stationed his chariots there (1 Kings 9:15). Many bloody battles were fought here, including the one where the good King Josiah tragically died. Because of this history of decisive wars, the book of Revelation uses the name Armageddon (Mount Megiddo) as a symbol for the final battle (Revelation 16:16)."}},{id:"dan",name:{nl:"Dan",en:"Dan"},region:{nl:"Israël (Noord)",en:"Israel (North)"},coords:[33.249,35.652],eras:[4],desc:{nl:"De noordelijkste grensplaats van Israël, berucht vanwege het gouden kalf van koning Jerobeam.",en:"The northernmost border town of Israel, infamous for King Jeroboam's golden calf."},story:{nl:"Dan fungeerde altijd als de uiterste noordgrens (vandaar de uitdrukking 'van Dan tot Berseba'). Na de scheuring van het koninkrijk was koning Jerobeam van het noordelijke rijk bang dat zijn volk naar Jeruzalem (in het zuiden) zou blijven gaan om te aanbidden. Om dit te stoppen, maakte hij twee gouden kalveren en plaatste er één in Bethel en één hier, in Dan. Dit leidde het noordelijke rijk direct in diepe en aanhoudende afgoderij (1 Koningen 12).",en:"Dan always served as the extreme northern border (hence the phrase 'from Dan to Beersheba'). After the split of the kingdom, King Jeroboam of the northern realm feared his people would keep going to Jerusalem (in the south) to worship. To stop this, he made two golden calves and placed one in Bethel and one here, in Dan. This immediately led the northern kingdom into deep and continuous idolatry (1 Kings 12)."}},{id:"joppa",name:{nl:"Joppa (Jaffa)",en:"Joppa (Jaffa)"},region:{nl:"Kustvlakte",en:"Coastal Plain"},coords:[32.054481,34.753039],eras:[4,7],desc:{nl:"De belangrijke havenstad van waaruit Jona vluchtte, en waar Petrus Tabitha uit de dood opwekte.",en:"The important port city from which Jonah fled, and where Peter raised Tabitha from the dead."},story:{nl:"Joppa (het moderne Jaffa) was in Bijbelse tijden de belangrijkste zeehaven van Israël. Hier werden de grote cederbomen uit Libanon aangevoerd voor de bouw van Salomo's Tempel. Jaren later was dit de stad waar de profeet Jona op een schip naar Tarsis vluchtte toen God hem naar Ninevé stuurde. In het Nieuwe Testament was Joppa de plek waar de apostel Petrus het meisje Tabitha opwekte uit de dood en een visioen op het dak kreeg over 'onreine' dieren, wat de zending naar de heidenen opende (Handelingen 9-10).",en:"Joppa (modern Jaffa) was Israel's main seaport in biblical times. Here the great cedar trees from Lebanon were brought in for the construction of Solomon's Temple. Years later, this was the city where the prophet Jonah fled onto a ship to Tarshish when God sent him to Nineveh. In the New Testament, Joppa was where the apostle Peter raised the girl Tabitha from the dead and received a vision on a rooftop about 'unclean' animals, opening missions to the Gentiles (Acts 9-10)."}},{id:"susa",name:{nl:"Susan (Susa)",en:"Susa"},region:{nl:"Perzië (Elam)",en:"Persia (Elam)"},coords:[32.18922,48.25778],eras:[5,6],desc:{nl:"De schitterende Perzische hoofdstad en het toneel van de boeken Esther, Nehemia en Daniël.",en:"The magnificent Persian capital and the setting of the books of Esther, Nehemiah, and Daniel."},story:{nl:"Na de val van Babylon werd Susan de imposante winterhoofdstad van het gigantische Perzische Rijk. Het Bijbelboek Esther speelt zich volledig af in de citadel van Susan, waar het Joodse weesmeisje Esther koningin werd en haar volk redde van genocide. Ook Nehemia diende hier als schenker van de koning voordat hij terugkeerde om de muren van Jeruzalem te herbouwen. Daniël ontving een van zijn belangrijke profetische visioenen nabij deze vestingstad (Daniël 8:2).",en:"After the fall of Babylon, Susa became the imposing winter capital of the massive Persian Empire. The biblical book of Esther is set entirely in the citadel of Susa, where the Jewish orphan girl Esther became queen and saved her people from genocide. Nehemiah also served here as cupbearer to the king before returning to rebuild the walls of Jerusalem. Daniel received one of his major prophetic visions near this fortress city (Daniel 8:2)."}},{id:"cana",name:{nl:"Kana",en:"Cana"},region:{nl:"Galilea",en:"Galilee"},coords:[32.8222,35.30269],eras:[6],desc:{nl:"Een dorp in Galilea waar Jezus Zijn eerste grote wonder deed tijdens een bruiloftsfeest.",en:"A village in Galilee where Jesus performed His first great miracle during a wedding feast."},story:{nl:"Tijdens een bruiloftsfeest in Kana, waar ook Maria, de moeder van Jezus, te gast was, raakte de wijn op - een enorme sociale blamage. Op aandringen van zijn moeder deed Jezus hier Zijn allereerste publieke wonder. Hij veranderde meer dan 600 liter water dat in reinigingsvaten zat in wijn van absolute topkwaliteit. De Bijbel zegt: 'Dit heeft Jezus gedaan als begin van zijn tekenen... en zijn leerlingen gingen in hem geloven' (Johannes 2).",en:"During a wedding feast in Cana, where Mary, the mother of Jesus, was also a guest, the wine ran out - a massive social disgrace. At his mother's prompting, Jesus performed His very first public miracle here. He turned over 150 gallons of water stored in purification jars into wine of absolute top quality. The Bible says: 'What Jesus did here... was the first of the signs through which he revealed his glory; and his disciples believed in him' (John 2)."}},{id:"caesarea_philippi",name:{nl:"Caesarea Filippi",en:"Caesarea Philippi"},region:{nl:"Hermon",en:"Hermon"},coords:[33.246111,35.693333],eras:[6],desc:{nl:"De noordelijke stad aan de voet van de Hermon, gedomineerd door heidense tempels, waar Petrus Jezus erkende als de Christus.",en:"The northern city at the foot of Hermon, dominated by pagan temples, where Peter confessed Jesus as the Christ."},story:{nl:"Caesarea Filippi was een centrum van afgoderij. Er stond een enorme tempel voor de Griekse god Pan, gebouwd voor een diepe, donkere grot die men de 'Poort van de Onderwereld' noemde. Juist op deze heidense plek vroeg Jezus aan zijn discipelen: 'Wie zeggen jullie dat Ik ben?'. Petrus antwoordde: 'U bent de Christus, de Zoon van de levende God'. Jezus beloofde daarop Zijn kerk te bouwen op die rots, en dat de 'poorten van het dodenrijk' haar niet zouden overweldigen (Mattheüs 16).",en:"Caesarea Philippi was a center of idolatry. There was a massive temple to the Greek god Pan, built in front of a deep, dark cave that people called the 'Gate of Hades'. Right in this pagan place, Jesus asked his disciples, 'Who do you say I am?'. Peter answered, 'You are the Messiah, the Son of the living God'. Jesus then promised to build His church on that rock, and that the 'gates of Hades' would not overcome it (Matthew 16)."}},{id:"bethany",name:{nl:"Bethanië",en:"Bethany"},region:{nl:"Judea",en:"Judea"},coords:[31.771661,35.255903],eras:[6],desc:{nl:"Het dorp net buiten Jeruzalem waar Jezus' vrienden Maria, Martha en Lazarus woonden.",en:"The village just outside Jerusalem where Jesus' friends Mary, Martha, and Lazarus lived."},story:{nl:"Bethanië was een vertrouwde uitvalsbasis voor Jezus wanneer Hij in de buurt van Jeruzalem was. Het was de woonplaats van Maria, Martha en hun broer Lazarus. Toen Lazarus ziek werd en stierf, kwam Jezus pas vier dagen later aan, en weende met de zussen (de kortste tekst in de Bijbel: 'Jezus weende'). Vervolgens riep Hij Lazarus levend uit het rotsgraf, een wonder dat het Sanhedrin ertoe dreef om de doodstraf over Jezus te eisen (Johannes 11). Vanaf de Olijfberg vlakbij Bethanië voer Jezus later op naar de hemel.",en:"Bethany was a familiar base for Jesus whenever He was near Jerusalem. It was the hometown of Mary, Martha, and their brother Lazarus. When Lazarus fell ill and died, Jesus arrived four days later, weeping with the sisters (the shortest verse in the Bible: 'Jesus wept'). He then called Lazarus alive out of the rock tomb, a miracle that drove the Sanhedrin to demand the death penalty for Jesus (John 11). Later, from the Mount of Olives near Bethany, Jesus ascended into heaven."}},{id:"caesarea",name:{nl:"Caesarea",en:"Caesarea Maritima"},region:{nl:"Judea (Kust)",en:"Judea (Coast)"},coords:[32.5,34.891667],eras:[6],desc:{nl:"De machtige Romeinse hoofdstad van Judea, gebouwd door Herodes de Grote.",en:"The mighty Roman capital of Judea, built by Herod the Great."},story:{nl:"Caesarea was het bestuurlijke en militaire centrum van de Romeinen in Israël; hier woonde ook Pontius Pilatus. Een Romeinse centurio in deze stad, Cornelius, kreeg een visioen om Petrus te laten halen. Toen Petrus het evangelie bracht, viel de Heilige Geest op de Romeinen – het beslissende moment waarop het christendom officieel voor de heidenen openging (Handelingen 10). Jaren later zat de apostel Paulus hier twee jaar lang als politiek gevangene opgesloten voordat hij zich op de keizer in Rome beriep.",en:"Caesarea was the administrative and military center for the Romans in Israel; Pontius Pilate also resided here. A Roman centurion in this city, Cornelius, received a vision to send for Peter. When Peter preached the gospel, the Holy Spirit fell upon the Romans - the decisive moment when Christianity officially opened to the Gentiles (Acts 10). Years later, the apostle Paul was imprisoned here as a political prisoner for two years before appealing to Caesar in Rome."}},{id:"ephesus",name:{nl:"Efeze",en:"Ephesus"},region:{nl:"Klein-Azië",en:"Asia Minor"},coords:[37.939125,27.3407],eras:[6],desc:{nl:"Een gigantische Romeinse metropool, beroemd om haar Artemistempel, waar Paulus jarenlang met succes preekte.",en:"A massive Roman metropolis, famous for its Temple of Artemis, where Paul preached successfully for years."},story:{nl:"Efeze was een van de grootste steden in de oudheid en huisvestte de Tempel van Artemis (een van de zeven wereldwonderen). Paulus verbleef hier bijna drie jaar; zijn zending was zó succesvol dat het evangelie zich door heel Klein-Azië verspreidde en de magie-industrie in elkaar stortte. Dit leidde tot een massale en gewelddadige opstand van zilversmeden in het grote amfitheater (Handelingen 19). Paulus schreef later de 'Efezebrief' aan deze sterk gegroeide kerk.",en:"Ephesus was one of the largest cities in antiquity and housed the Temple of Artemis (one of the seven wonders of the world). Paul stayed here for nearly three years; his mission was so successful that the gospel spread throughout Asia Minor and the magic industry collapsed. This led to a massive and violent riot by silversmiths in the great amphitheater (Acts 19). Paul later wrote the 'Epistle to the Ephesians' to this rapidly growing church."}},{id:"corinth",name:{nl:"Korinthe",en:"Corinth"},region:{nl:"Achaia (Griekenland)",en:"Achaea (Greece)"},coords:[37.905785,22.878741],eras:[6],desc:{nl:"Een welvarende, zedeloze handelsstad waar Paulus een van zijn belangrijkste, maar meest complexe gemeentes stichtte.",en:"A wealthy, immoral trade city where Paul founded one of his most important but most complex churches."},story:{nl:"Korinthe was een knooppunt van wereldhandel, berucht om haar extreme rijkdom, heidense tempels en losbandigheid. Paulus verbleef er maar liefst anderhalf jaar, verdiende er zijn brood als tentenmaker samen met Priscilla en Aquila, en zag een grote kerk ontstaan ondanks zware oppositie (Handelingen 18). De gemeente in Korinthe worstelde echter met veel problemen (zoals verdeeldheid en zedeloosheid), wat Paulus ertoe bracht de zeer persoonlijke en theologische 1e en 2e Korinthe-brieven te schrijven.",en:"Corinth was a hub of world trade, notorious for its extreme wealth, pagan temples, and debauchery. Paul stayed there for a full year and a half, working as a tentmaker with Priscilla and Aquila, and saw a large church emerge despite heavy opposition (Acts 18). The church in Corinth struggled with many problems, however (such as division and immorality), which prompted Paul to write the highly personal and theological 1st and 2nd Corinthian epistles."}},{id:"athens",name:{nl:"Athene",en:"Athens"},region:{nl:"Achaia (Griekenland)",en:"Achaea (Greece)"},coords:[37.971851,23.726738],eras:[6],desc:{nl:"Het centrum van de Griekse filosofie, waar Paulus een meesterlijke toespraak hield over de 'Onbekende God'.",en:"The center of Greek philosophy, where Paul delivered a masterful speech about the 'Unknown God'."},story:{nl:"Toen Paulus wachtte op zijn medewerkers in Athene, ergerde hij zich kapot aan de stad, die letterlijk vol stond met afgodsbeelden. Hij raakte in debat met Stoïcijnse en Epicurische filosofen. Ze brachten hem naar de Areopagus (de rots van Ares), het intellectuele hart van de stad. Daar hield Paulus een briljante redevoering waarin hij inspeelde op een lokaal altaar voor 'Een Onbekende God'. Hij legde de opstanding van Jezus uit; sommigen spotten, maar anderen kwamen tot geloof (Handelingen 17).",en:"While waiting for his companions in Athens, Paul was greatly distressed to see that the city was full of idols. He engaged in debate with Stoic and Epicurean philosophers. They brought him to the Areopagus, the intellectual heart of the city. There Paul delivered a brilliant speech, using a local altar to 'An Unknown God' as his starting point. He explained the resurrection of Jesus; some sneered, but others believed (Acts 17)."}},{id:"patmos",name:{nl:"Patmos",en:"Patmos"},region:{nl:"Egeïsche Zee",en:"Aegean Sea"},coords:[37.325,26.541667],eras:[6],desc:{nl:"Het ruwe gevangeniseiland waar de apostel Johannes verbleef en het boek Openbaring ontving.",en:"The rugged prison island where the apostle John stayed and received the book of Revelation."},story:{nl:"Aan het einde van de eerste eeuw, vermoedelijk onder de vervolgingen van de Romeinse keizer Domitianus, werd de oude apostel Johannes als gevangene verbannen naar het eiland Patmos. 'Op de dag van de Heer' raakte hij in vervoering door de Geest en ontving hij visioenen van de opgestane, verheerlijkte Jezus. Hij kreeg de opdracht deze profetische beelden over de eindtijd en de terugkeer van Christus op te schrijven voor zeven gemeenten. Dit indrukwekkende verslag kennen we nu als het laatste boek van de Bijbel: de Openbaring van Johannes.",en:"At the end of the first century, presumably under the persecutions of the Roman emperor Domitian, the elderly apostle John was exiled as a prisoner to the island of Patmos. 'On the Lord's Day' he was caught up in the Spirit and received visions of the resurrected, glorified Jesus. He was instructed to write down these prophetic images about the end times and the return of Christ for seven churches. This impressive account is now known as the final book of the Bible: the Revelation to John."}},{id:"bethphage",name:{nl:"Bethfagé",en:"Bethphage"},region:{nl:"Judea",en:"Judea"},coords:[31.7766,35.2458],eras:[6],desc:{nl:"Een dorpje op de Olijfberg, vanwaar Jezus het veulen liet halen voor Zijn intocht.",en:"A small village on the Mount of Olives where Jesus sent for the donkey colt."},story:{nl:"Bethfagé (wat 'Huis der onrijpe vijgen' betekent) was een klein dorpje op de helling van de Olijfberg, dichtbij Bethanië. Vanaf hier stuurde Jezus twee discipelen vooruit om een ezelsveulen te halen, waarmee Hij Zijn triomfantelijke intocht in Jeruzalem begon, om zo de profetie van Zacharia te vervullen (Mattheüs 21:1-11).",en:"Bethphage (meaning 'House of unripe figs') was a small village on the Mount of Olives near Bethany. From here, Jesus sent two disciples ahead to bring a donkey colt, on which He made His triumphal entry into Jerusalem, fulfilling the prophecy of Zechariah (Matthew 21:1-11)."}},{id:"kidron_valley",name:{nl:"Dal Kidron",en:"Kidron Valley"},region:{nl:"Judea",en:"Judea"},coords:[31.7758,35.2392],eras:[1,2,3,4,5,6],desc:{nl:"Het diepe dal tussen Jeruzalem en de Olijfberg.",en:"The deep valley separating Jerusalem from the Mount of Olives."},story:{nl:"De beek Kidron stroomt door het dal dat Jeruzalem scheidt van de Olijfberg in het oosten. Koning David trok er al wenend overheen toen hij vluchtte voor zijn zoon Absalom (2 Samuël 15). Eeuwen later stak Jezus, op de nacht van Zijn verraad, ditzelfde donkere dal over op weg naar de Hof van Gethsémané (Johannes 18:1).",en:"The Kidron Brook flows through the valley that separates Jerusalem from the Mount of Olives to the east. King David crossed it weeping when fleeing from his son Absalom (2 Samuel 15). Centuries later, on the night of His betrayal, Jesus crossed this same dark valley on His way to the Garden of Gethsemane (John 18:1)."}},{id:"jericho",name:{nl:"Jericho",en:"Jericho"},region:{nl:"Stad",en:"City"},coords:[31.8711,35.4433],eras:[1,2,3,5,6],desc:{nl:"De eerste stad in Kanaän die door Israël werd veroverd onder leiding van Jozua.",en:"The first city in Canaan conquered by Israel under Joshua's leadership."},story:{nl:`**Archeologische en historische betekenis**
Jericho (Tell es-Sultan) is een van de oudste bewoonde steden ter wereld, gelegen in de Jordaanvallei. Archeologen hebben massieve muren uit de oudheid gevonden.

**Culturele en geografische context**
Gelegen nabij een belangrijke doorwaadbare plaats van de Jordaan, vormde het de toegangspoort tot het centrale heuvelland van Kanaän. De oase werd gevoed door sterke zoetwaterbronnen.

**Theologische betekenis**
De val van de muren van Jericho door geloof (Jozua 6) en de redding van Rachab tonen aan dat de verovering van het Beloofde Land Gods werk was. In het Nieuwe Testament genas Jezus hier de blinde Bartimeüs en bezocht Hij Zacheüs.`,en:`**Archaeological and historical significance**
Jericho is one of the oldest continuously inhabited cities in the world. Archaeological excavations have revealed massive ancient defensive walls.

**Cultural and geographical context**
Situated near a major ford of the Jordan River, it controlled the main ascent into the Canaanite highlands. The city was a lush oasis fed by a powerful spring.

**Theological significance**
The miraculous fall of Jericho's walls (Joshua 6) proved that the conquest of Canaan was God's victory. In the New Testament, Jesus healed blind Bartimaeus and saved Zacchaeus here.`}},{id:"gibeon",name:{nl:"Gibeon",en:"Gibeon"},region:{nl:"Stad",en:"City"},coords:[31.8475,35.1844],eras:[2,3,4],desc:{nl:"Een grote Kanaänitische stad die door een list een verbond met Jozua sloot.",en:"A large Canaanite city that famously tricked Joshua into a peace treaty."},story:{nl:`**Archeologische en historische betekenis**
Geïdentificeerd met el-Jib, ten noordwesten van Jeruzalem. Opgravingen hebben de beroemde 'vijver van Gibeon' (2 Samuël 2) blootgelegd, een enorm in de rotsen uitgehouwen watersysteem.

**Culturele en geografische context**
Gibeon was een koninklijke stad, groter dan Ai. Doordat zij zich aan Israël overgaven, braken zij de verenigde Kanaänitische verdediging in het zuiden.

**Theologische betekenis**
God gebruikte het haastige (maar bindende) verbond met de Gibeonieten om de zuidelijke koningen te verslaan. Hier stond de zon stil op het gebed van Jozua, een van de meest ontzagwekkende theofanieën in het Oude Testament (Jozua 10).`,en:`**Archaeological and historical significance**
Identified with el-Jib. Excavators found the famous 'pool of Gibeon' (2 Samuel 2), a massive rock-cut water system and ancient winery.

**Cultural and geographical context**
Gibeon was a royal city, greater than Ai. By surrendering to Israel, they strategically fractured the Canaanite southern alliance.

**Theological significance**
God used Israel's binding oath to the Gibeonites to draw out and defeat the southern kings. It was here that the sun stood still at Joshua's prayer, demonstrating God's absolute sovereignty over creation (Joshua 10).`}},{id:"shiloh",name:{nl:"Silo",en:"Shiloh"},region:{nl:"Stad",en:"City"},coords:[32.0553,35.2894],eras:[2,3],desc:{nl:"Het eerste grote religieuze centrum van Israël waar de Tabernakel stond.",en:"Israel's first major religious center where the Tabernacle was erected."},story:{nl:`**Archeologische en historische betekenis**
Geïdentificeerd met Khirbet Seilun in Efraïm. Archeologische vondsten tonen aan dat het in de ijzertijd I een belangrijk cultisch centrum was, dat later met geweld werd verwoest (waarschijnlijk door de Filistijnen).

**Culturele en geografische context**
Silo lag centraal in het heuvelland. Na de verovering van Kanaän werd hier de tabernakel opgezet, en de verdeling van het land werd vanuit Silo voltooid (Jozua 18).

**Theologische betekenis**
Eeuwenlang was dit de woonplaats van God. Hier bad Hanna om Samuël. Nadat de priesters (de zonen van Eli) corrupt werden, liet God toe dat de Ark werd veroverd en Silo werd verwoest. Profeten gebruikten later de 'ruïnes van Silo' als waarschuwing dat God zelfs Zijn eigen heiligdom verlaat als het volk volhardt in zonde (Jeremia 7:12).`,en:`**Archaeological and historical significance**
Identified with Khirbet Seilun. Excavations confirm it was a major Israelite cultic center in Iron Age I that suffered a violent destruction, likely by the Philistines.

**Cultural and geographical context**
Centrally located in the hill country of Ephraim. After the initial conquest, the Tabernacle was set up here, and the land allotments were finalized (Joshua 18).

**Theological significance**
For centuries, Shiloh was the dwelling place of God's presence. Here Hannah prayed for Samuel. Because of the extreme wickedness of Eli's sons, God allowed the Ark to be captured and Shiloh destroyed. The prophets later used Shiloh as a chilling warning against religious presumption (Jeremiah 7:12).`}},{id:"hazor",name:{nl:"Hazor",en:"Hazor"},region:{nl:"Stad",en:"City"},coords:[33.0183,35.5683],eras:[2,3,4],desc:{nl:"De grootste en machtigste Kanaänitische stad, 'het hoofd van al die koninkrijken'.",en:"The largest and most powerful Canaanite city, 'the head of all those kingdoms'."},story:{nl:`**Archeologische en historische betekenis**
Tel Hazor is de grootste archeologische vindplaats van Israël. Opgravingen bevestigen een massieve verwoesting door brand in de 13e eeuw v.Chr., die exact overeenkomt met de Bijbelse beschrijving in Jozua 11.

**Culturele en geografische context**
Gelegen in de Hula-vallei (Boven-Galilea) beheerste Hazor de grote internationale handelsroute (Via Maris) tussen Egypte en Mesopotamië.

**Theologische betekenis**
Hazor verzamelde de noordelijke alliantie tegen Jozua. Door de vernietiging van de grootste macht in Kanaän door de Israëlieten, bewees God dat geen enkele aardse vesting, hoe groot ook, stand kan houden tegen Zijn belofte.`,en:`**Archaeological and historical significance**
Tel Hazor is the largest biblical-era site in Israel. Excavations show a massive, fiery destruction in the Late Bronze Age (13th century BC), perfectly matching Joshua 11.

**Cultural and geographical context**
Located in the Hula Valley, it dominated the Via Maris, the major international trade route connecting Egypt with Mesopotamia.

**Theological significance**
Hazor was the head of the northern Canaanite alliance against Israel. By handing the most formidable fortress in the land over to Joshua, God proved that no human coalition could stop His redemptive plan.`}},{id:"dead_sea",name:{nl:"Zoutzee (Dode Zee)",en:"Salt Sea (Dead Sea)"},region:{nl:"Zee / Meer",en:"Sea / Lake"},coords:[31.5,35.5],eras:[1,2,3,4,5,6],desc:{nl:"Het laagste punt op aarde, de oostelijke grens van Juda.",en:"The lowest point on earth, serving as the eastern border of Judah."},story:{nl:`**Archeologische en historische betekenis**
In de Bijbel bekend als de Zoutzee, de Zee van de Vlakte of de Oostzee. De rotsachtige grotten langs de kustlijn herbergden later de Essenen en de beroemde Dode Zee-rollen.

**Culturele en geografische context**
Gelegen op ruim 400 meter onder zeeniveau, met een zoutgehalte van 34%, is het levenloos. Het vormde een formidabele natuurlijke grens in het oosten van Israël.

**Theologische betekenis**
De Zoutzee is een stille getuige van het oordeel over Sodom; het eens vruchtbare dal werd een woestenij. Echter, Ezechiël 47 profeteert een dag waarop levend water vanuit de tempel in Jeruzalem in deze zee zal stromen, waardoor de dode wateren gezond worden en vol zullen zitten met vissen — een prachtig beeld van Gods toekomstige herstel.`,en:`**Archaeological and historical significance**
Known biblically as the Salt Sea, Sea of the Arabah, or the Eastern Sea. Its rugged shores later housed the Essenes who preserved the Dead Sea Scrolls.

**Cultural and geographical context**
Situated over 400 meters below sea level with 34% salinity, it supports no aquatic life. It formed the imposing eastern geographical boundary of Judah.

**Theological significance**
The Dead Sea stands as a geographical monument to the judgment of Sodom, turning a once-fertile valley into a wasteland. However, Ezekiel 47 prophesies that one day, living water flowing from the Temple will heal the Dead Sea, making it teem with life—a powerful symbol of ultimate redemption.`}},{id:"arnon",name:{nl:"Rivier de Arnon",en:"River Arnon"},region:{nl:"Rivier",en:"River"},coords:[31.4666,35.5666],eras:[2,3,4],desc:{nl:"De grote kloof die de grens vormde tussen Moab en de Amorieten.",en:"The massive gorge that formed the boundary between Moab and the Amorites."},story:{nl:`**Archeologische en historische betekenis**
De Arnon (Wadi Mujib) is de 'Grand Canyon' van Jordanië. De steile kliffen maakten het een van de belangrijkste en meest verdedigbare grenzen in de oudheid.

**Culturele en geografische context**
Tijdens de woestijnreis vormde deze rivier de grens tussen de Moabieten in het zuiden en het koninkrijk van de Amoriet Sihon in het noorden.

**Theologische betekenis**
Israël trok de Arnon over na hun overwinningen, wat hun eerste echte intrede in betwist gebied markeerde voorafgaand aan de intocht in Kanaän (Numeri 21). Het toonde dat de Heere niet alleen in de woestijn, maar ook in bewoond territorium voor hen streed.`,en:`**Archaeological and historical significance**
The Arnon (Wadi Mujib) is the 'Grand Canyon' of Jordan. Its steep cliffs made it one of the most formidable and defensible natural borders in antiquity.

**Cultural and geographical context**
During the Exodus, this deep gorge divided the territory of the Moabites to the south from the Amorite kingdom of Sihon to the north.

**Theological significance**
Crossing the Arnon marked Israel's transition from wandering in the desert to actively dispossessing nations before entering Canaan (Numbers 21). It demonstrated that the Lord was handing over fortified, inhabited lands into their hands.`}},{id:"jabbok",name:{nl:"Rivier de Jabbok",en:"Jabbok River"},region:{nl:"Rivier",en:"River"},coords:[32.1833,35.5666],eras:[1,2],desc:{nl:"De rivier waar Jakob met de Engel worstelde.",en:"The river where Jacob wrestled with the Angel of the Lord."},story:{nl:`**Archeologische en historische betekenis**
De Jabbok (Zarqa rivier) snijdt door de bergen van Gilead in het huidige Jordanië en stroomt in de Jordaan.

**Culturele en geografische context**
Het vormde een natuurlijke grens in het Overjordaanse. Jakob stuurde hier in de nacht zijn hele familie de doorwaadbare plaats over, toen hij Esau tegemoet trok.

**Theologische betekenis**
Bij de Jabbok bleef Jakob alleen achter en worstelde hij de hele nacht met God. Hier werd zijn heup ontwricht, maar ontving hij de zegen en zijn nieuwe naam: *Israël* ("Hij die met God strijdt"). Het water van de Jabbok is voor altijd verbonden met de transformatie van de bedrieger Jakob naar de aartsvader Israël.`,en:`**Archaeological and historical significance**
The Jabbok (modern Zarqa River) cuts through the mountains of Gilead in Jordan, flowing westward into the Jordan River.

**Cultural and geographical context**
It was a major territorial boundary. Jacob sent his family across the ford of the Jabbok in the dead of night as he prepared to face his estranged brother Esau.

**Theological significance**
At the Jabbok, Jacob was left alone and wrestled all night with the Angel of the Lord. Here his hip was dislocated, his self-reliance broken, and his name changed to *Israel* ('He who strives with God'). It remains the ultimate biblical site of personal brokenness, blessing, and transformation.`}},{id:"gethsemane",name:{nl:"Gethsémané",en:"Gethsemane"},region:{nl:"Tuin",en:"Garden"},coords:[31.7794,35.2397],eras:[6],desc:{nl:"De olijfgaard waar Jezus in bittere doodsstrijd bad en werd verraden.",en:"The olive grove where Jesus prayed in agony and was betrayed."},story:{nl:`**Archeologische en historische betekenis**
De naam betekent 'oliepers'. Gethsémané bevond zich op de westelijke helling van de Olijfberg, direct aan de overkant van het Kidrondal nabij de tempel. Er staan hier olijfbomen die, hoewel misschien niet uit de 1e eeuw, extreem oud zijn.

**Culturele en geografische context**
Het was een besloten tuin waar Jezus regelmatig kwam met Zijn discipelen. Omdat het buiten de stadsmuren lag, was het de ideale plek voor Judas om Hem in het donker, weg van de menigte, te verraden.

**Theologische betekenis**
Hier streed Jezus de ultieme geestelijke strijd. Waar de eerste Adam faalde in de Hof van Eden en zijn eigen wil koos, onderwierp de Tweede Adam (Jezus) in de Hof van Gethsémané Zijn wil volledig aan de Vader ("Niet Mijn wil, maar Uw wil geschiede"), zelfs tot het zweten van bloed toe. Dit was het geestelijke startpunt van de kruisiging.`,en:`**Archaeological and historical significance**
Meaning 'oil press', Gethsemane was located on the lower western slopes of the Mount of Olives, just across the Kidron Valley from the Temple Mount.

**Cultural and geographical context**
It was a secluded garden and a familiar retreat for Jesus and His disciples. Being outside the city walls, it provided the darkness and isolation Judas needed to betray Him away from the crowds.

**Theological significance**
Gethsemane is the site of ultimate spiritual agony. Where the first Adam failed in a Garden (Eden) by asserting his own will, the Last Adam (Jesus) triumphed in a Garden by fully surrendering His will to the Father ("Not my will, but Yours, be done"). The redemption of the world was secured in this crushing press.`}},{id:"bethesda",name:{nl:"Badwater Bethesda",en:"Pool of Bethesda"},region:{nl:"Poel",en:"Pool"},coords:[31.7814,35.2358],eras:[6],desc:{nl:"De baden in Jeruzalem waar Jezus een man genas die al 38 jaar verlamd was.",en:"The pools in Jerusalem where Jesus healed a man paralyzed for 38 years."},story:{nl:`**Archeologische en historische betekenis**
Johannes 5 beschrijft Bethesda als een poel met vijf zuilengangen. Eeuwenlang dachten critici dat dit verzonnen was, tot in de 19e eeuw de ruïnes van exact twee enorme, door vijf portieken omgeven waterbekkens werden opgegraven ten noorden van het tempelplein.

**Culturele en geografische context**
Het lag vlakbij de Schaapspoort in Jeruzalem en diende mogelijk als wasplaats voor de schapen die voor het tempeloffer bestemd waren. Het was ook een verzamelplaats voor de zieken.

**Theologische betekenis**
De poel vertegenwoordigde de onmacht van het menselijke systeem: de lamme man had niemand om hem te helpen, hoe lang hij ook wachtte op de 'beweging van het water'. Toen Jezus sprak: "Sta op, neem uw bedasse op en wandel", toonde Hij dat redding niet komt door rituele tradities of menselijke inspanning, maar enkel door de soevereine kracht van Zijn Woord.`,en:`**Archaeological and historical significance**
John 5 describes Bethesda as a pool with five colonnades. For centuries, skeptics doubted its existence until archaeologists excavated two massive, adjacent reservoirs surrounded by five porticoes near the Sheep Gate in Jerusalem.

**Cultural and geographical context**
Located just north of the Temple Mount, it was likely used to wash sacrificial sheep. It was also a notorious gathering place for the sick and disabled seeking healing.

**Theological significance**
The paralyzed man had waited 38 years, totally helpless, hoping the waters would heal him. Jesus bypassed the superstitions and human limitations entirely. By simply commanding, "Get up, take up your bed, and walk," Jesus demonstrated that salvation and healing come not through ritual effort, but solely by the sovereign power of the Son of God.`}},{id:"philippi",name:{nl:"Filippi",en:"Philippi"},region:{nl:"Stad",en:"City"},coords:[41.0122,24.2847],eras:[6],desc:{nl:"De eerste stad in Europa waar het evangelie werd gepredikt, in Macedonië.",en:"The first European city where the gospel was preached, located in Macedonia."},story:{nl:`**Archeologische en historische betekenis**
Filippi was een belangrijke Romeinse kolonie (gesticht door de vader van Alexander de Grote) langs de strategische Via Egnatia, die Rome met het Oosten verbond.

**Culturele en geografische context**
Omdat het een kolonie was, genoten de inwoners Romeins burgerrecht. Er waren kennelijk weinig Joden; er was geen synagoge, dus Paulus vond de gelovigen biddend aan de oever van een rivier.

**Theologische betekenis**
Nadat Paulus het 'Macedonische visioen' kreeg, bracht hij hier voor het eerst het evangelie naar Europa. Hier kwamen Lydia, het slavenmeisje, en de gevangenbewaarder tot geloof — een rijke, een slaaf en een ambtenaar. Ondanks dat Paulus en Silas hier gegeseld en in de kerker gegooid werden (waar ze om middernacht zongen!), ontstond hier een van de meest geliefde en genereuze gemeenten van het Nieuwe Testament (zie de Filippenzenbrief).`,en:`**Archaeological and historical significance**
Philippi was a prominent Roman colony located on the Via Egnatia, the major Roman road connecting Rome with the East.

**Cultural and geographical context**
Its citizens enjoyed elite Roman privileges. It lacked a substantial Jewish population (hence no synagogue), which is why Paul found believers praying outside the city by a river.

**Theological significance**
Following the 'Macedonian call', Philippi became the beachhead of the gospel in Europe. The first converts—Lydia (a wealthy merchant), a demon-possessed slave girl, and a Roman jailer—showcase the universal power of the gospel to break all social barriers. Even though Paul and Silas were beaten and imprisoned here, they sang hymns at midnight, leading to a miraculous earthquake and the birth of a deeply affectionate church.`}},{id:"bethsaida",name:{nl:"Bethsaïda",en:"Bethsaida"},region:{nl:"Stad",en:"City"},coords:[32.9094,35.63],eras:[6],desc:{nl:"Vissersdorp aan het Meer van Galilea; de geboorteplaats van Petrus, Andreas en Filippus.",en:"Fishing village on the Sea of Galilee; hometown of Peter, Andrew, and Philip."},story:{nl:`**Archeologische en historische betekenis**
De naam betekent 'Huis van de visserij'. Archeologen debatteren over de exacte locatie (et-Tell of el-Araj), maar beide liggen aan de noordelijke kust van het Meer van Galilea nabij de monding van de Jordaan.

**Culturele en geografische context**
Het lag strategisch dicht bij Kafarnaüm. Jezus trok Zich vaak terug naar de eenzame streken rond Bethsaïda.

**Theologische betekenis**
Jezus deed hier vele van Zijn indrukwekkendste wonderen, waaronder de spijziging van de 5.000 (vlakbij) en de genezing van een blinde man. Toch sprak Hij later een zwaar wee uit over Bethsaïda (samen met Chorazin) wegens hun hardnekkige ongeloof, ondanks de vele krachten die er waren geschied (Mattheüs 11:21).`,en:`**Archaeological and historical significance**
Meaning 'House of Fishing', Bethsaida's exact location is debated between et-Tell and el-Araj, both situated on the northern shore of the Sea of Galilee.

**Cultural and geographical context**
A prominent fishing hub near Capernaum, it was the hometown of at least three apostles: Peter, Andrew, and Philip.

**Theological significance**
Jesus performed many mighty works here, including healing a blind man and the nearby feeding of the 5,000. Tragically, despite witnessing so much divine power, the city refused to repent, leading Jesus to pronounce a severe judgment of "Woe to you, Bethsaida!" (Matthew 11:21).`}},{id:"iconium",name:{nl:"Iconium",en:"Iconium"},region:{nl:"Stad",en:"City"},coords:[37.8713,32.4846],eras:[6],desc:{nl:"Een belangrijke stad in Galatië waar Paulus en Barnabas een grote schare bereikten, maar ook zware vervolging ontmoetten.",en:"A major city in Galatia where Paul and Barnabas saw great revival and intense persecution."},story:{nl:`**Archeologische en historische betekenis**
Iconium (het moderne Konya in Turkije) was een oeroude stad die een belangrijke Hellenistische en Romeinse kern vormde op de route door Klein-Azië.

**Culturele en geografische context**
Als bruisende handelspost was het cultureel divers. Paulus bezocht Iconium tijdens zijn eerste zendingsreis.

**Theologische betekenis**
In Iconium spraken Paulus en Barnabas zo vrijmoedig dat een grote menigte Joden en Grieken geloofde. Echter, ongelovige stadsgenoten stookten de gemoederen zo hoog op dat de apostelen moesten vluchten voor steniging (Hand. 14). Toch bleven ze terugkeren om de nieuwe gelovigen te versterken, wat toont dat de vroege kerk standhield dwars door vervolging heen.`,en:`**Archaeological and historical significance**
Iconium (modern Konya, Turkey) was an ancient and prosperous city in the Roman province of Galatia.

**Cultural and geographical context**
Located on a major trade route across Asia Minor, it was a melting pot of Phrygian, Greek, Roman, and Jewish cultures.

**Theological significance**
During Paul's first missionary journey, he and Barnabas preached boldly in the synagogue, resulting in a massive conversion of both Jews and Greeks. However, bitter opposition divided the city, forcing them to flee a stoning plot (Acts 14). Paul's later letter to the Galatians was directed in part to these very believers, urging them to stand fast in the gospel of grace.`}},{id:"lystra",name:{nl:"Lystra",en:"Lystra"},region:{nl:"Stad",en:"City"},coords:[37.5613,32.1977],eras:[6],desc:{nl:"Hier werd Paulus gestenigd en voor dood achtergelaten, en het is de thuisstad van Timotheüs.",en:"The city where Paul was stoned and left for dead, and the hometown of Timothy."},story:{nl:`**Archeologische en historische betekenis**
Lystra lag in Lycaonië, afgelegen van de hoofdroutes. Archeologen hebben de locatie geïdentificeerd, maar ze is grotendeels onopgegraven.

**Culturele en geografische context**
Het was een agrarische Romeinse kolonie. De bevolking sprak nog hun eigen Lycaonische taal en had een sterk heidens geloof; er was schijnbaar geen Joodse synagoge.

**Theologische betekenis**
Toen Paulus hier een verlamde genas, dacht de menigte dat hij en Barnabas goden (Hermes en Zeus) waren. Toen Paulus dit afwees, sloeg de stemming door opgehitste Joden direct om: ze stenigden Paulus en sleepten hem de stad uit (Hand. 14). Wonderbaarlijk stond hij op. Jaren later vond Paulus in dit zelfde Lystra de jonge Timotheüs, die zijn belangrijkste geestelijke zoon zou worden.`,en:`**Archaeological and historical significance**
Located in the region of Lycaonia, Lystra was a Roman colony established by Augustus. The unexcavated tell contains remains of this rural outpost.

**Cultural and geographical context**
It was deeply pagan and provincial. The locals spoke their native Lycaonian dialect, which initially caused a dangerous miscommunication with Paul and Barnabas.

**Theological significance**
After healing a lame man, the crowds tried to worship Paul and Barnabas as Hermes and Zeus. Soon after, hostile Jews arrived and incited the very same crowd to stone Paul, dragging him out of the city for dead (Acts 14). Miraculously, Paul rose up. From this fiery trial emerged young Timothy, a native of Lystra, who became Paul's most trusted protege.`}},{id:"antioch_pisidia",name:{nl:"Antiochië (in Pisidië)",en:"Antioch of Pisidia"},region:{nl:"Stad",en:"City"},coords:[38.3055,31.2825],eras:[6],desc:{nl:"Het Romeinse centrum van Galatië, waar Paulus zijn grote preek hield over rechtvaardiging door geloof.",en:"The Roman center of Galatia where Paul delivered his pivotal sermon on justification by faith."},story:{nl:`**Archeologische en historische betekenis**
Een aanzienlijke militaire en administratieve Romeinse kolonie in centraal Turkije. Uitgebreide opgravingen tonen grote tempels en een aquaduct.

**Culturele en geografische context**
Ondanks de naam lag het op de grens van Frygië en Pisidië. Het had een aanzienlijke en invloedrijke Joodse gemeenschap.

**Theologische betekenis**
Hier, in de synagoge, hield Paulus zijn eerste opgenomen preek in Handelingen (hfdst. 13). Hij verbond de hele geschiedenis van Israël direct met Jezus, en verklaarde: "In Hem wordt eenieder die gelooft, gerechtvaardigd van alles waarvan u door de wet van Mozes niet gerechtvaardigd kon worden." Toen de Joden de boodschap afwezen, keerden Paulus en Barnabas zich hier expliciet naar de heidenen, wat de loop van de kerkgeschiedenis veranderde.`,en:`**Archaeological and historical significance**
A major Roman military colony in central Asia Minor. Extensive ruins include a vast aqueduct, theater, and imperial temples.

**Cultural and geographical context**
It served as a strategic hub for Roman control over the mountainous interior, and hosted a prominent Jewish synagogue.

**Theological significance**
Acts 13 records Paul's longest and most foundational sermon here in the synagogue. He summarized Israel's history culminating in Christ, introducing the core doctrine of justification by faith apart from the Law of Moses. When the Jewish leadership rejected the message, Paul boldly declared they were now turning to the Gentiles, setting the paradigm for his entire global ministry.`}},{id:"paphos",name:{nl:"Pafos",en:"Paphos"},region:{nl:"Stad",en:"City"},coords:[34.7594,32.4111],eras:[6],desc:{nl:"De hoofdstad van Cyprus waar Paulus een tovenaar verblindde en de Romeinse proconsul tot geloof kwam.",en:"The capital of Cyprus where Paul blinded a sorcerer and won the Roman proconsul to Christ."},story:{nl:`**Archeologische en historische betekenis**
Pafos was de Romeinse hoofdstad van het eiland Cyprus en de zetel van de provinciale gouverneur (proconsul).

**Culturele en geografische context**
Het lag aan de westkust van Cyprus en was beroemd om de enorme cultus rondom de godin Aphrodite, wat het een bolwerk van afgoderij en occulte praktijken maakte.

**Theologische betekenis**
Tijdens de eerste zendingsreis werden Paulus en Barnabas ontboden door de Romeinse proconsul Sergius Paulus. Een Joodse tovenaar (Elymas) probeerde de gouverneur van het geloof af te houden. Vol van de Heilige Geest sprak Paulus een oordeel uit waardoor Elymas tijdelijk blind werd. Dit machtsvertoon van God overtuigde de proconsul, wat Pafos de plek maakt van de eerste grote bekering van een hoge Romeinse functionaris (Hand. 13).`,en:`**Archaeological and historical significance**
Paphos served as the administrative capital of Roman Cyprus and the seat of its proconsul (governor).

**Cultural and geographical context**
Located on the western coast, the city was infamous for its massive sanctuary to Aphrodite, making it a dark center of pagan fertility rites and occultism.

**Theological significance**
On their first journey, Paul and Barnabas were opposed here by a Jewish sorcerer named Elymas, who tried to turn the Roman proconsul away from the faith. Filled with the Spirit, Paul struck the sorcerer temporarily blind. Seeing this sheer supremacy of God's power over the occult, the proconsul believed (Acts 13)—marking a major political breakthrough for the early church.`}},{id:"smyrna",name:{nl:"Smyrna",en:"Smyrna"},region:{nl:"Stad",en:"City"},coords:[38.4237,27.1428],eras:[6],desc:{nl:"Eén van de zeven gemeenten van Openbaring, de vervolgde kerk.",en:"One of the seven churches of Revelation, the persecuted church."},story:{nl:`**Archeologische en historische betekenis**
Smyrna (het huidige Izmir) was een van de welvarendste steden van Asia, prachtig gelegen aan een baai met tempels voor Romeinse keizers.

**Culturele en geografische context**
Het was een fel loyale bondgenoot van Rome, wat het belijden van Jezus als ultieme Koning daar levensgevaarlijk maakte.

**Theologische betekenis**
In Openbaring 2 krijgt Smyrna enkel lof (samen met Filadelfia). Jezus belooft deze zwaar beproefde gelovigen de 'kroon des levens' als zij trouw blijven tot de dood. Later werd hun bisschop, Polycarpus (een leerling van Johannes), hier op hoge leeftijd levend verbrand voor zijn geloof.`,en:`**Archaeological and historical significance**
Smyrna (modern Izmir) was one of the crown jewels of the province of Asia, fiercely proud of its imperial cult temples.

**Cultural and geographical context**
Its deep loyalty to Rome made emperor worship a patriotic duty, making Christians extremely vulnerable to state persecution.

**Theological significance**
In Revelation 2, Smyrna receives no rebuke from Christ, only comfort. Jesus acknowledges their crushing poverty and coming imprisonment, promising the 'crown of life' to those faithful unto death. Decades later, its beloved bishop Polycarp was burned at the stake here, famously refusing to deny Christ.`}},{id:"pergamum",name:{nl:"Pergamum",en:"Pergamum"},region:{nl:"Stad",en:"City"},coords:[39.1222,27.18],eras:[6],desc:{nl:"Eén van de zeven gemeenten, de kerk waar 'de troon van de satan' was.",en:"One of the seven churches, located where 'Satan's throne' is."},story:{nl:`**Archeologische en historische betekenis**
Pergamum bezat een wereldberoemde bibliotheek en reusachtige tempels, waaronder het enorme Altaar van Zeus, hoog op de akropolis.

**Culturele en geografische context**
Het was het bestuurlijke en religieuze zwaartepunt van Asia, een duistere vesting van heidense culten.

**Theologische betekenis**
Jezus noemt het in Openbaring 2 de plaats waar "de troon van de satan is". Ondanks dat de gelovigen onder enorme druk stonden (Antipas werd er als martelaar gedood), waarschuwde Jezus de kerk voor compromissen en het tolereren van de leer van Bileam, waarbij ze wereldse zonden in de kerk toelieten.`,en:`**Archaeological and historical significance**
Pergamum boasted an acropolis towering over the valley, holding a world-class library and the massive Altar of Zeus.

**Cultural and geographical context**
It was the administrative capital of Asia and a dark, intimidating center of pagan worship and emperor cults.

**Theological significance**
In Revelation 2, Jesus calls it the place "where Satan's throne is." While commending them for holding fast to His name even when Antipas was martyred, Christ strongly rebuked them for compromising with the world, specifically by tolerating the idolatrous and immoral teachings of Balaam.`}},{id:"laodicea",name:{nl:"Laodicea",en:"Laodicea"},region:{nl:"Stad",en:"City"},coords:[37.8389,29.1069],eras:[6],desc:{nl:"De lauwe kerk uit Openbaring, de enige van de zeven zonder enige lof.",en:"The lukewarm church of Revelation, the only one receiving no praise."},story:{nl:`**Archeologische en historische betekenis**
Laodicea was extreem rijk. Het was een centrum van bankieren, medische wetenschap (oogzalf) en textiel (zwarte wol). Toen een aardbeving de stad verwoestte, weigerden ze keizerlijke hulp omdat ze zichzelf konden redden.

**Culturele en geografische context**
Omdat het water van Laodicea vol kalk zat en via aquaducten van ver moest komen, was het berucht om zijn 'lauwe', vieze water (in tegenstelling tot hete baden in Hiërapolis en koud bronwater in Kolosse).

**Theologische betekenis**
In Openbaring 3 gebruikt Jezus de lokale situatie treffend: de kerk dacht rijk te zijn, maar was geestelijk "ellendig, naakt en blind". Omdat hun geloof 'lauw' was (niet nuttig heet, noch verfrissend koud), dreigde Jezus hen uit Zijn mond te spuwen. Toch staat juist hier de tedere belofte: "Zie, Ik sta aan de deur en Ik klop."`,en:`**Archaeological and historical significance**
Laodicea was fabulously wealthy, famous for its banking, a medical school producing eye salve, and premium black wool.

**Cultural and geographical context**
Lacking a natural water supply, water was piped in via aqueducts, arriving lukewarm and heavily calcified—unlike the therapeutic hot springs of nearby Hierapolis or the cold streams of Colossae.

**Theological significance**
In Revelation 3, Jesus brilliantly uses their local pride to expose their spiritual bankruptcy. They claimed they were rich and needed nothing, but Christ called them "wretched, blind, and naked." Because they were 'lukewarm'—useless to the thirsty and useless for healing—He threatened to spit them out. Yet, it ends with His tenderest appeal: "Behold, I stand at the door and knock."`}},{id:"tigris",coords:[36,42.5],name:{nl:"Tigris",en:"Tigris River"},region:{nl:"Mesopotamië",en:"Mesopotamia"},desc:{nl:"De grote oostelijke rivier van Mesopotamië.",en:"The great eastern river of Mesopotamia."},story:{nl:"De Tigris stroomt van het Turkse oosten door Irak en is een van de twee belangrijkste rivieren in de Bijbelse geschiedenis, naast de Eufraat.",en:"The Tigris flows from eastern Turkey through Iraq and is one of the two major rivers in biblical history, alongside the Euphrates."},eras:[1,2,3]},{id:"euphrates",coords:[34,44.5],name:{nl:"Eufraat",en:"Euphrates River"},region:{nl:"Mesopotamië",en:"Mesopotamia"},desc:{nl:"De westelijke rivier van Mesopotamië die de vruchtbare vlakte voedt.",en:"The western river of Mesopotamia that waters the fertile plain."},story:{nl:"De Eufraat wordt vaak in de Bijbel genoemd als grens en bron van leven, en het land tussen Tigris en Eufraat werd het hart van de Bijbelse beschaving.",en:"The Euphrates is often mentioned as a boundary and source of life in the Bible, with the land between the Tigris and Euphrates as the cradle of biblical civilization."},eras:[1,2,3]},{id:"jordan",coords:[31.8,35.5],name:{nl:"Jordaan",en:"Jordan River"},region:{nl:"Israël",en:"Israel"},desc:{nl:"Kleine, maar belangrijke rivier die Israëlieten doopte.",en:"A small but pivotal river that baptized the Israelites."},story:{nl:"De Jordaan stroomt van het Meer van Galilea tot de Dode Zee en vormt een cruciale locatie in het nieuwtestamentische doopverhaal.",en:"The Jordan flows from the Sea of Galilee to the Dead Sea and serves as a crucial location in the New Testament baptism story."},eras:[2,3,4]},{id:"gaza",coords:[31.504,34.4644],name:{nl:"Gaza",en:"Gaza"},region:{nl:"Filistea (Kustvlakte)",en:"Philistia (Coastal Plain)"},desc:{nl:"Filistijnse havenstad waar Simson stierf, en bestemming van de woestijnweg van Filippus.",en:"Philistine port city where Samson died, and the destination of Philip's desert road."},story:{nl:"Gaza was een van de vijf grote Filistijnse steden en lag op de oude handelsweg tussen Egypte en Kanaän. Hier werd Simson gevangen, geblind en liet hij de tempel van Dagon instorten (Richteren 16). In het Nieuwe Testament stuurde een engel Filippus op de \"woestijnweg\" van Jeruzalem naar Gaza, waar hij de Ethiopische hoveling doopte (Handelingen 8:26). De stad bestaat nog en staat vandaag opnieuw centraal in het nieuws.",en:"Gaza was one of the five great Philistine cities and lay on the ancient trade road between Egypt and Canaan. Here Samson was captured, blinded and brought down the temple of Dagon (Judges 16). In the New Testament an angel sent Philip down the \"desert road\" from Jerusalem to Gaza, where he baptised the Ethiopian official (Acts 8:26). The city still exists and is once again at the centre of the news today."},verses:["Richteren 16:21", "Handelingen 8:26"],eras:[3, 6, 7]},{id:"ashkelon",coords:[31.663889,34.545833],name:{nl:"Askelon",en:"Ashkelon"},region:{nl:"Filistea (Kustvlakte)",en:"Philistia (Coastal Plain)"},desc:{nl:"Filistijnse havenstad aan de Middellandse Zee, een van de vijf steden van de Filistijnen.",en:"Philistine port city on the Mediterranean, one of the five cities of the Philistines."},story:{nl:"Askelon was een van de vijf Filistijnse steden (Jozua 13:3). Simson doodde hier dertig man om de kleren voor zijn raadsel te betalen (Richteren 14:19). De profeten kondigden haar ondergang aan (Jeremia 47:5, Zefanja 2:4). Opgravingen vonden een haven en een stadspoort uit de Bronstijd.",en:"Ashkelon was one of the five Philistine cities (Joshua 13:3). Here Samson killed thirty men to pay for the garments of his riddle (Judges 14:19). The prophets announced its downfall (Jeremiah 47:5, Zephaniah 2:4). Excavations found a harbour and a Bronze Age city gate."},verses:["Jozua 13:3", "Richteren 14:19", "Jeremia 47:5"],eras:[3, 4]},{id:"ashdod",coords:[31.7572,34.6578],name:{nl:"Asdod",en:"Ashdod"},region:{nl:"Filistea (Kustvlakte)",en:"Philistia (Coastal Plain)"},desc:{nl:"Filistijnse stad waar de ark van God in de tempel van Dagon stond.",en:"Philistine city where the ark of God stood in the temple of Dagon."},story:{nl:"Na de slag bij Eben-Ezer brachten de Filistijnen de ark van God naar de tempel van Dagon in Asdod. Het beeld van Dagon viel voor de ark neer en er kwam een plaag over de stad (1 Samuël 5). In het Nieuwe Testament heet de stad Azotus; daar werd Filippus teruggevonden nadat hij de Ethiopiër had gedoopt (Handelingen 8:40).",en:"After the battle of Ebenezer the Philistines brought the ark of God to the temple of Dagon in Ashdod. The statue of Dagon fell before the ark and a plague struck the city (1 Samuel 5). In the New Testament the city is called Azotus; Philip was found there after baptising the Ethiopian (Acts 8:40)."},verses:["1 Samuël 5:1", "Handelingen 8:40"],eras:[3, 4, 6]},{id:"gath",coords:[31.69972,34.84694],name:{nl:"Gat",en:"Gath"},region:{nl:"Filistea (Kustvlakte)",en:"Philistia (Coastal Plain)"},desc:{nl:"De stad van de reus Goliath.",en:"The city of the giant Goliath."},story:{nl:"Gat was een van de vijf Filistijnse steden en de stad van Goliath (1 Samuël 17:4). David vluchtte voor Saul naar koning Achis van Gat (1 Samuël 21:10) en woonde later een tijd onder de Filistijnen. Koning Uzzia brak de muur van Gat af (2 Kronieken 26:6). De plaats wordt gelijkgesteld met Tell es-Safi.",en:"Gath was one of the five Philistine cities and the city of Goliath (1 Samuel 17:4). David fled from Saul to King Achish of Gath (1 Samuel 21:10) and later lived among the Philistines for a time. King Uzziah broke down the wall of Gath (2 Chronicles 26:6). The site is identified with Tell es-Safi."},verses:["1 Samuël 17:4", "1 Samuël 21:10", "2 Kronieken 26:6"],eras:[3, 4]},{id:"ekron",coords:[31.7775,34.851944],name:{nl:"Ekron",en:"Ekron"},region:{nl:"Filistea (Kustvlakte)",en:"Philistia (Coastal Plain)"},desc:{nl:"Filistijnse stad waar de ark een plaag bracht en vandaar naar Israël terugkeerde.",en:"Philistine city where the ark brought a plague and returned from to Israel."},story:{nl:"Ekron was de meest noordelijke van de vijf Filistijnse steden. Toen de ark van God daarheen werd gebracht, brak er een plaag uit en stuurden de Filistijnen hem terug naar Beth-Semes (1 Samuël 5-6). Later raadpleegde koning Ahazia de god van Ekron, Baäl-Zebub, wat Elia hem verweet (2 Koningen 1).",en:"Ekron was the northernmost of the five Philistine cities. When the ark of God was brought there a plague broke out and the Philistines sent it back to Beth Shemesh (1 Samuel 5-6). Later King Ahaziah consulted the god of Ekron, Baal-Zebub, for which Elijah rebuked him (2 Kings 1)."},verses:["1 Samuël 5:10", "1 Samuël 6:16", "2 Koningen 1:2"],eras:[3, 4]},{id:"lachish",coords:[31.565278,34.849167],name:{nl:"Lachis",en:"Lachish"},region:{nl:"Juda (Sefela)",en:"Judah (Shephelah)"},desc:{nl:"Sterke vestingstad in Juda, belegerd door Sanherib en Nebukadnezar.",en:"Strong fortress city in Judah, besieged by Sennacherib and Nebuchadnezzar."},story:{nl:"Na Jeruzalem was Lachis de belangrijkste vesting van Juda. Sanherib belegerde de stad in 701 v.Chr. (2 Koningen 18:14); de reliëfs van die belegering uit zijn paleis in Nineve zijn nu in het British Museum. Later belegerde Nebukadnezar haar (Jeremia 34:7). De \"Lachis-brieven\", scherven uit 588 v.Chr., beschrijven de laatste dagen van Juda.",en:"After Jerusalem, Lachish was the most important fortress of Judah. Sennacherib besieged the city in 701 BC (2 Kings 18:14); the reliefs of that siege from his palace in Nineveh are now in the British Museum. Later Nebuchadnezzar besieged it (Jeremiah 34:7). The \"Lachish letters\", potsherds from 588 BC, describe the last days of Judah."},verses:["Jozua 10:31", "2 Koningen 18:14", "Jeremia 34:7"],eras:[3, 4, 5]},{id:"gezer",coords:[31.859167,34.919167],name:{nl:"Gezer",en:"Gezer"},region:{nl:"Kanaän (Sefela)",en:"Canaan (Shephelah)"},desc:{nl:"Versterkte stad aan de weg naar Jeruzalem, door Farao als bruidsschat aan Salomo gegeven.",en:"Fortified city on the road to Jerusalem, given by Pharaoh to Solomon as a dowry."},story:{nl:"Gezer lag bij de kruising van de Via Maris en de weg naar Jeruzalem. Josua versloeg de koning van Gezer (Jozua 10:33). Een Egyptische farao veroverde en verbrandde de stad en gaf haar aan zijn dochter, Salomo's vrouw (1 Koningen 9:16). Salomo bouwde haar weer op (1 Koningen 9:17). Opgravingen vonden een zespoortige stadspoort uit zijn tijd.",en:"Gezer lay at the crossing of the Via Maris and the road to Jerusalem. Joshua defeated the king of Gezer (Joshua 10:33). An Egyptian pharaoh captured and burned the city and gave it to his daughter, Solomon's wife (1 Kings 9:16). Solomon rebuilt it (1 Kings 9:17). Excavations found a six-chambered city gate from his time."},verses:["Jozua 10:33", "1 Koningen 9:16", "1 Koningen 9:17"],eras:[3, 4]},{id:"bethshean",coords:[32.503611,35.503056],name:{nl:"Beth-Sean",en:"Beth Shean"},region:{nl:"Jizreëlvallei",en:"Jezreel Valley"},desc:{nl:"Stad waar het lichaam van Saul aan de muur werd gehangen.",en:"City where the body of Saul was hung on the wall."},story:{nl:"Beth-Sean lag op een strategisch punt tussen de Jizreëlvallei en de Jordaanvallei. De Israëlieten konden de stad aanvankelijk niet innemen (Jozua 17:11). Na Sauls dood op de Gilboa hingen de Filistijnen zijn lichaam en dat van zijn zonen aan de muur van Beth-Sean; mannen uit Jabes in Gilead haalden ze daar weg (1 Samuël 31).",en:"Beth Shean stood at a strategic point between the Jezreel Valley and the Jordan Valley. The Israelites could not at first take the city (Joshua 17:11). After Saul's death on Gilboa the Philistines hung his body and those of his sons on the wall of Beth Shean; men from Jabesh Gilead took them down (1 Samuel 31)."},verses:["Jozua 17:11", "1 Samuël 31:10", "1 Samuël 31:12"],eras:[3, 4]},{id:"jezreel",coords:[32.557853,35.327953],name:{nl:"Jizreël",en:"Jezreel"},region:{nl:"Jizreëlvallei",en:"Jezreel Valley"},desc:{nl:"Stad van Achab en Izebel en van de wijngaard van Naboth.",en:"City of Ahab and Jezebel and of Naboth's vineyard."},story:{nl:"Jizreël was de zomerresidentie van koning Achab. Hier liet Izebel Naboth ter dood brengen om zijn wijngaard te bemachtigen (1 Koningen 21). Elia profeteerde Achabs ondergang, en Jehu doodde later Izebel in Jizreël (2 Koningen 9). De naam betekent \"God zaait\".",en:"Jezreel was King Ahab's summer residence. Here Jezebel had Naboth put to death to seize his vineyard (1 Kings 21). Elijah prophesied Ahab's downfall, and Jehu later killed Jezebel at Jezreel (2 Kings 9). The name means \"God sows\"."},verses:["1 Koningen 21:1", "2 Koningen 9:30"],eras:[4]},{id:"tiberias",coords:[32.773611,35.544167],name:{nl:"Tiberias",en:"Tiberias"},region:{nl:"Galilea",en:"Galilee"},desc:{nl:"Stad aan het Meer van Galilea, genoemd naar keizer Tiberius.",en:"City on the Sea of Galilee, named after Emperor Tiberius."},story:{nl:"Herodes Antipas stichtte Tiberias rond 20 n.Chr. aan de westoever van het meer en noemde de stad naar keizer Tiberius. Het meer wordt in het Johannesevangelie daarom ook \"Zee van Tiberias\" genoemd (Johannes 6:1, 21:1). Na het jaar 70 werd de stad een belangrijk centrum van het Joodse geleerde leven.",en:"Herod Antipas founded Tiberias around AD 20 on the western shore of the lake and named it after Emperor Tiberius. In John's Gospel the lake is therefore also called the \"Sea of Tiberias\" (John 6:1, 21:1). After AD 70 the city became an important centre of Jewish scholarship."},verses:["Johannes 6:1", "Johannes 6:23", "Johannes 21:1"],eras:[6]},{id:"magdala",coords:[32.827069,35.513552],name:{nl:"Magdala",en:"Magdala"},region:{nl:"Galilea",en:"Galilee"},desc:{nl:"Thuisstad van Maria Magdalena.",en:"Home town of Mary Magdalene."},story:{nl:"Magdala lag aan de westoever van het Meer van Galilea en was een welvarende stad van de visverwerking. Maria uit Magdala, uit wie Jezus zeven demonen had verdreven, volgde Hem en was als eerste getuige van de opstanding (Lucas 8:2, Johannes 20:1). Opgravingen vonden een synagoge uit de eerste eeuw.",en:"Magdala lay on the western shore of the Sea of Galilee and was a prosperous fish-processing town. Mary of Magdala, from whom Jesus had cast out seven demons, followed Him and was the first witness of the resurrection (Luke 8:2, John 20:1). Excavations found a first-century synagogue."},verses:["Mattheüs 15:39", "Lucas 8:2", "Johannes 20:1"],eras:[6]},{id:"sychar",coords:[32.21776,35.28897],name:{nl:"Sichar",en:"Sychar"},region:{nl:"Samaria",en:"Samaria"},desc:{nl:"Plaats bij Jakobs bron, waar Jezus met de Samaritaanse vrouw sprak.",en:"Place by Jacob's well, where Jesus spoke with the Samaritan woman."},story:{nl:"Bij Jakobs bron aan de rand van Sichar sprak Jezus met een Samaritaanse vrouw en sprak over \"levend water\" en over aanbidding in geest en waarheid (Johannes 4). Veel Samaritanen uit de stad kwamen tot geloof (Johannes 4:39).",en:"At Jacob's well on the edge of Sychar Jesus spoke with a Samaritan woman about \"living water\" and about worship in spirit and truth (John 4). Many Samaritans from the town came to believe (John 4:39)."},verses:["Johannes 4:5", "Johannes 4:39"],eras:[6]},{id:"emmaus",coords:[31.8393,34.989458],name:{nl:"Emmaüs",en:"Emmaus"},region:{nl:"Judea",en:"Judea"},desc:{nl:"Dorp waar Jezus na de opstanding twee leerlingen vergezelde en het brood brak.",en:"Village where Jesus walked with two disciples after the resurrection and broke bread."},story:{nl:"Op de dag van de opstanding liepen twee leerlingen van Jeruzalem naar Emmaüs, zestig stadiën ver. Jezus voegde zich bij hen, legde de Schriften uit en werd herkend bij het breken van het brood (Lucas 24:13-35). De exacte ligging is omstreden; hier is Emmaüs-Nicopolis weergegeven.",en:"On the day of the resurrection two disciples walked from Jerusalem to Emmaus, sixty stadia away. Jesus joined them, explained the Scriptures and was recognised in the breaking of bread (Luke 24:13-35). The exact location is disputed; Emmaus-Nicopolis is shown here."},verses:["Lucas 24:13", "Lucas 24:31"],eras:[6]},{id:"sidon",coords:[33.560985,35.371944],name:{nl:"Sidon",en:"Sidon"},region:{nl:"Fenicië",en:"Phoenicia"},desc:{nl:"Oude Fenicische havenstad, zuster van Tyrus.",en:"Ancient Phoenician port city, sister of Tyre."},story:{nl:"Sidon was een van de oudste Fenicische havensteden en wordt al in Genesis 10:15 genoemd. Izebel, de vrouw van Achab, was de dochter van de koning van de Sidoniërs (1 Koningen 16:31). Jezus bezocht het gebied van Tyrus en Sidon en genas daar de dochter van een Kananese vrouw (Mattheüs 15:21-28).",en:"Sidon was one of the oldest Phoenician port cities and is already mentioned in Genesis 10:15. Jezebel, the wife of Ahab, was the daughter of the king of the Sidonians (1 Kings 16:31). Jesus visited the region of Tyre and Sidon and healed the daughter of a Canaanite woman there (Matthew 15:21-28)."},verses:["Genesis 10:15", "1 Koningen 16:31", "Mattheüs 15:21"],eras:[4, 6]},{id:"tadmor",coords:[34.547,38.274],name:{nl:"Tadmor (Palmyra)",en:"Tadmor (Palmyra)"},region:{nl:"Syrië",en:"Syria"},desc:{nl:"Woestijnstad in de Syrische oase, door Salomo versterkt.",en:"Desert city in the Syrian oasis, built up by Solomon."},story:{nl:"Salomo bouwde Tadmor in de woestijn en versterkte de steden in Hamath (2 Kronieken 8:4). De oase werd later, onder de naam Palmyra, een rijke karavaanstad aan de handelsroute tussen het Romeinse Rijk en het Oosten.",en:"Solomon built Tadmor in the wilderness and fortified the cities of Hamath (2 Chronicles 8:4). Under the name Palmyra the oasis later became a rich caravan city on the trade route between the Roman Empire and the East."},verses:["2 Kronieken 8:4"],eras:[4]},{id:"hamath",coords:[35.1365,36.75],name:{nl:"Hamath",en:"Hamath"},region:{nl:"Syrië",en:"Syria"},desc:{nl:"Stad aan de Orontes en noordgrens van het beloofde land.",en:"City on the Orontes and the northern border of the promised land."},story:{nl:"Hamath (het huidige Hama) lag aan de Orontes en markeerde de noordgrens van het beloofde land (\"de ingang van Hamath\", Numeri 34:8). Toi, de koning van Hamath, sloot vrede met David (2 Samuël 8:9). Jerobeam II herstelde de grens van Israël tot daar (2 Koningen 14:25).",en:"Hamath (modern Hama) lay on the Orontes and marked the northern border of the promised land (\"the entrance of Hamath\", Numbers 34:8). Toi, king of Hamath, made peace with David (2 Samuel 8:9). Jeroboam II restored the border of Israel as far as there (2 Kings 14:25)."},verses:["2 Samuël 8:9", "2 Koningen 14:25", "Numeri 34:8"],eras:[4]},{id:"arvad",coords:[34.856082,35.858485],name:{nl:"Arvad",en:"Arvad"},region:{nl:"Fenicië",en:"Phoenicia"},desc:{nl:"Fenicisch eilandstad, bekend om haar zeelieden.",en:"Phoenician island city, known for its sailors."},story:{nl:"Arvad lag op een eiland voor de kust van Fenicië en wordt in Genesis 10:18 genoemd. Ezechiël roemt haar mannen als roeiers en verdedigers van Tyrus (Ezechiël 27:8, 11). Het eiland heet nu Arwad en ligt voor de Syrische kust.",en:"Arvad lay on an island off the coast of Phoenicia and is mentioned in Genesis 10:18. Ezekiel praises its men as oarsmen and defenders of Tyre (Ezekiel 27:8, 11). The island is now called Arwad and lies off the Syrian coast."},verses:["Genesis 10:18", "Ezechiël 27:8"],eras:[4]},{id:"carchemish",coords:[36.829722,38.015],name:{nl:"Karchemis",en:"Carchemish"},region:{nl:"Aram (Noord-Syrië)",en:"Aram (Northern Syria)"},desc:{nl:"Slagveld waar Nebukadnezar in 605 v.Chr. Egypte versloeg.",en:"Battlefield where Nebuchadnezzar defeated Egypt in 605 BC."},story:{nl:"Karchemis lag aan de Eufraat en was een belangrijke Hettitische en Assyrische stad. Farao Necho trok erheen en Josia van Juda sneuvelde bij Megiddo toen hij hem tegenhield (2 Kronieken 35:20-24). In 605 v.Chr. versloeg Nebukadnezar het Egyptische leger bij Karchemis (Jeremia 46:2) en werd Babel de grootmacht.",en:"Carchemish lay on the Euphrates and was an important Hittite and Assyrian city. Pharaoh Necho marched there and Josiah of Judah fell at Megiddo when he tried to stop him (2 Chronicles 35:20-24). In 605 BC Nebuchadnezzar defeated the Egyptian army at Carchemish (Jeremiah 46:2) and Babylon became the great power."},verses:["Jesaja 10:9", "Jeremia 46:2", "2 Kronieken 35:20"],eras:[4, 5]},{id:"riblah",coords:[34.431703,36.545259],name:{nl:"Ribla",en:"Riblah"},region:{nl:"Syrië (Orontesvallei)",en:"Syria (Orontes Valley)"},desc:{nl:"Hoofdkwartier van Nebukadnezar waar Sedekia werd veroordeeld.",en:"Nebuchadnezzar's headquarters where Zedekiah was sentenced."},story:{nl:"Ribla lag in het Orontes-dal en was een legerkamp van Farao Necho (2 Koningen 23:33) en later van Nebukadnezar. Na de val van Jeruzalem werd koning Sedekia naar Ribla gebracht; daar werden zijn zonen voor zijn ogen gedood en werd hij zelf geblind (2 Koningen 25:6-7, Jeremia 39:5-7).",en:"Riblah lay in the Orontes valley and was a camp of Pharaoh Necho (2 Kings 23:33) and later of Nebuchadnezzar. After the fall of Jerusalem King Zedekiah was brought to Riblah; there his sons were killed before his eyes and he himself was blinded (2 Kings 25:6-7, Jeremiah 39:5-7)."},verses:["2 Koningen 25:6", "Jeremia 39:5", "2 Koningen 23:33"],eras:[4, 5]},{id:"elath",coords:[29.530676,34.999999],name:{nl:"Elat",en:"Elath"},region:{nl:"Edom (Rode Zee)",en:"Edom (Red Sea)"},desc:{nl:"Havenstad aan de Rode Zee, bij Ezion-Geber.",en:"Port city on the Red Sea, near Ezion-geber."},story:{nl:"Elat lag aan het noordelijke uiteinde van de Golf van Akaba, bij Ezion-Geber, en was Salomo's haven voor zijn vloot (1 Koningen 9:26). Israël trok er langs op weg naar Kanaän (Deuteronomium 2:8). Uzzia herbouwde Elat en bracht het terug bij Juda (2 Koningen 14:22). Vandaag liggen Eilat en Akaba op deze plek.",en:"Elath lay at the northern end of the Gulf of Aqaba, near Ezion-geber, and was Solomon's port for his fleet (1 Kings 9:26). Israel passed by it on the way to Canaan (Deuteronomy 2:8). Uzziah rebuilt Elath and restored it to Judah (2 Kings 14:22). Today Eilat and Aqaba lie at this spot."},verses:["Deuteronomium 2:8", "1 Koningen 9:26", "2 Koningen 14:22"],eras:[2, 4]},{id:"tarsus",coords:[36.913028,34.892056],name:{nl:"Tarsus",en:"Tarsus"},region:{nl:"Kilikië",en:"Cilicia"},desc:{nl:"Geboortestad van de apostel Paulus.",en:"Birthplace of the apostle Paul."},story:{nl:"Tarsus was een belangrijke handels- en universiteitsstad in Kilikië. Paulus noemt zichzelf \"een Jood uit Tarsus, burger van een niet onaanzienlijke stad\" (Handelingen 21:39). Na zijn bekering ging hij naar Tarsus, vanwaar Barnabas hem ophaalde om in Antiochië te werken (Handelingen 9:30, 11:25).",en:"Tarsus was an important trading and university city in Cilicia. Paul calls himself \"a Jew from Tarsus, a citizen of no obscure city\" (Acts 21:39). After his conversion he went to Tarsus, from where Barnabas fetched him to work in Antioch (Acts 9:30, 11:25)."},verses:["Handelingen 9:11", "Handelingen 21:39", "Handelingen 22:3"],eras:[6]},{id:"colossae",coords:[37.78664,29.25994],name:{nl:"Kolosse",en:"Colossae"},region:{nl:"Frygië (Klein-Azië)",en:"Phrygia (Asia Minor)"},desc:{nl:"Stad in de Lycusvallei, waar de brief van Paulus naar toe ging.",en:"City in the Lycus Valley, to which Paul's letter was sent."},story:{nl:"Kolosse lag in de Lycusvallei, dicht bij Laodicea en Hierapolis. Epafras stichtte er de gemeente. Paulus schreef vanuit de gevangenis zijn brief aan de Kolossenzen, en de slaaf Onesimus, om wie de brief aan Filemon gaat, kwam uit deze stad.",en:"Colossae lay in the Lycus Valley, near Laodicea and Hierapolis. Epaphras founded the church there. From prison Paul wrote his letter to the Colossians, and the slave Onesimus, the subject of the letter to Philemon, came from this city."},verses:["Kolossenzen 1:2", "Kolossenzen 4:13"],eras:[6]},{id:"sardis",coords:[38.488333,28.040278],name:{nl:"Sardes",en:"Sardis"},region:{nl:"Lydië (Klein-Azië)",en:"Lydia (Asia Minor)"},desc:{nl:"Een van de zeven gemeenten van Openbaring, \"je hebt de naam dat je leeft, maar je bent dood\".",en:"One of the seven churches of Revelation, \"you have the name of being alive, but you are dead\"."},story:{nl:"Sardes was de rijke hoofdstad van het Lydische rijk onder koning Croesus. De gemeente kreeg de scherpe waarschuwing: \"Gij hebt den naam dat gij leeft, en gij zijt dood\" (Openbaring 3:1). Enkelen hadden hun kleren niet bezoedeld (Openbaring 3:4).",en:"Sardis was the rich capital of the Lydian kingdom under King Croesus. The church received the sharp warning: \"You have the name of being alive, and you are dead\" (Revelation 3:1). A few had not soiled their garments (Revelation 3:4)."},verses:["Openbaring 3:1", "Openbaring 3:4"],eras:[6]},{id:"philadelphia",coords:[38.35,28.516667],name:{nl:"Filadelfia",en:"Philadelphia"},region:{nl:"Lydië (Klein-Azië)",en:"Lydia (Asia Minor)"},desc:{nl:"Een van de zeven gemeenten van Openbaring, \"ik heb voor u een geopende deur gesteld\".",en:"One of the seven churches of Revelation, \"I have set before you an open door\"."},story:{nl:"Filadelfia (het huidige Alaşehir) lag in een aardbevingsgebied. De gemeente wordt geprezen: \"Gij hebt een kleine kracht en hebt Mijn woord bewaard\" en kreeg een geopende deur die niemand kan sluiten (Openbaring 3:7-8).",en:"Philadelphia (modern Alaşehir) lay in an earthquake zone. The church is praised: \"you have but little power, and yet you have kept my word\", and received an open door that no one can shut (Revelation 3:7-8)."},verses:["Openbaring 3:7", "Openbaring 3:8"],eras:[6]},{id:"thyatira",coords:[38.92021,27.83655],name:{nl:"Thyatira",en:"Thyatira"},region:{nl:"Lydië (Klein-Azië)",en:"Lydia (Asia Minor)"},desc:{nl:"Stad van Lydia, de purperverkoopster, en een van de zeven gemeenten van Openbaring.",en:"City of Lydia, the seller of purple, and one of the seven churches of Revelation."},story:{nl:"Thyatira was bekend om zijn handwerkgilden en purperverf. Lydia, de purperverkoopster die in Filippi tot geloof kwam, kwam uit deze stad (Handelingen 16:14). De gemeente werd geprezen voor haar liefde en volharding, maar gewaarschuwd voor de valse profetes \"Izebel\" (Openbaring 2:18-29).",en:"Thyatira was known for its craft guilds and purple dye. Lydia, the seller of purple who came to faith in Philippi, came from this city (Acts 16:14). The church was praised for its love and perseverance, but warned against the false prophetess \"Jezebel\" (Revelation 2:18-29)."},verses:["Handelingen 16:14", "Openbaring 2:18"],eras:[6]},{id:"miletus",coords:[37.531111,27.275556],name:{nl:"Milete",en:"Miletus"},region:{nl:"Ionië (Klein-Azië)",en:"Ionia (Asia Minor)"},desc:{nl:"Havenstad waar Paulus afscheid nam van de oudsten van Efeze.",en:"Port city where Paul said farewell to the elders of Ephesus."},story:{nl:"Op zijn terugreis naar Jeruzalem liet Paulus de oudsten van Efeze naar Milete komen en nam ontroerend afscheid van hen (Handelingen 20:17-38). Hij zei dat zij zijn gezicht niet meer zouden zien. Later liet hij Trofimus ziek in Milete achter (2 Timoteüs 4:20).",en:"On his way back to Jerusalem Paul had the elders of Ephesus come to Miletus and took a moving farewell of them (Acts 20:17-38). He said they would not see his face again. Later he left Trophimus sick at Miletus (2 Timothy 4:20)."},verses:["Handelingen 20:15", "Handelingen 20:17", "2 Timoteüs 4:20"],eras:[6]},{id:"troas",coords:[39.751944,26.158611],name:{nl:"Troas",en:"Troas"},region:{nl:"Mysië (Klein-Azië)",en:"Mysia (Asia Minor)"},desc:{nl:"Havenstad waar Paulus de roep uit Macedonië ontving.",en:"Port city where Paul received the call from Macedonia."},story:{nl:"In Troas kreeg Paulus het visioen van de man uit Macedonië die vroeg: \"Kom over en help ons\" (Handelingen 16:9). Zo kwam het evangelie naar Europa. Bij een later bezoek wekte hij hier Eutychus op, die uit het raam viel tijdens zijn lange preek (Handelingen 20:7-12).",en:"At Troas Paul received the vision of the man from Macedonia who asked: \"Come over and help us\" (Acts 16:9). In this way the gospel came to Europe. On a later visit he raised Eutychus here, who fell from the window during his long sermon (Acts 20:7-12)."},verses:["Handelingen 16:8", "Handelingen 20:7", "2 Timoteüs 4:13"],eras:[6]},{id:"perga",coords:[36.960353,30.853686],name:{nl:"Perge",en:"Perga"},region:{nl:"Pamfylië (Klein-Azië)",en:"Pamphylia (Asia Minor)"},desc:{nl:"Eerste halte van Paulus' eerste zendingsreis in Klein-Azië.",en:"First stop of Paul's first missionary journey in Asia Minor."},story:{nl:"Vanuit Cyprus voer Paulus naar Perge in Pamfylië; daar verliet Johannes Markus hen en keerde terug naar Jeruzalem (Handelingen 13:13). Op de terugweg predikten ze het woord in Perge (Handelingen 14:25).",en:"From Cyprus Paul sailed to Perga in Pamphylia; there John Mark left them and returned to Jerusalem (Acts 13:13). On the way back they preached the word in Perga (Acts 14:25)."},verses:["Handelingen 13:13", "Handelingen 14:25"],eras:[6]},{id:"derbe",coords:[37.348569,33.361453],name:{nl:"Derbe",en:"Derbe"},region:{nl:"Lykaonië (Klein-Azië)",en:"Lycaonia (Asia Minor)"},desc:{nl:"Stad waar Paulus het evangelie verkondigde na zijn gevecht in Lystra.",en:"City where Paul preached the gospel after being stoned in Lystra."},story:{nl:"Na de steniging in Lystra reisde Paulus met Barnabas naar Derbe, waar zij veel discipelen maakten (Handelingen 14:20-21). Gaius uit Derbe reisde later met Paulus mee (Handelingen 20:4).",en:"After the stoning at Lystra Paul travelled with Barnabas to Derbe, where they made many disciples (Acts 14:20-21). Gaius of Derbe later travelled with Paul (Acts 20:4)."},verses:["Handelingen 14:6", "Handelingen 14:20", "Handelingen 20:4"],eras:[6]},{id:"berea",coords:[40.518333,22.2],name:{nl:"Berea",en:"Berea"},region:{nl:"Macedonië",en:"Macedonia"},desc:{nl:"Stad waar de Joden dagelijks de Schriften onderzochten.",en:"City where the Jews examined the Scriptures daily."},story:{nl:"Na de vervolging in Tessalonica kwamen Paulus en Silas in Berea. De Joden daar waren \"edeler dan die van Tessalonica\": zij ontvingen het woord gewillig en onderzochten dagelijks de Schriften of het zo was (Handelingen 17:10-12).",en:"After the persecution in Thessalonica Paul and Silas came to Berea. The Jews there were \"more noble than those in Thessalonica\": they received the word eagerly and examined the Scriptures daily to see if it was so (Acts 17:10-12)."},verses:["Handelingen 17:10", "Handelingen 17:11"],eras:[6]},{id:"hierapolis",coords:[37.926616,29.127375],name:{nl:"Hierapolis",en:"Hierapolis"},region:{nl:"Frygië (Klein-Azië)",en:"Phrygia (Asia Minor)"},desc:{nl:"Stad met warmwaterbronnen, naast Laodicea en Kolosse.",en:"City with hot springs, next to Laodicea and Colossae."},story:{nl:"Hierapolis lag bij warme bronnen in de Lycusvallei, naast Laodicea en Kolosse. Paulus noemt Epafras' inzet voor de gemeenten in deze drie steden (Kolossenzen 4:13). De witte kalkterrassen van het huidige Pamukkale liggen hier.",en:"Hierapolis lay by hot springs in the Lycus Valley, next to Laodicea and Colossae. Paul mentions Epaphras' labour for the churches in these three cities (Colossians 4:13). The white limestone terraces of modern Pamukkale are found here."},verses:["Kolossenzen 4:13"],eras:[6]},{id:"thessalonica",coords:[40.637771,22.945767],name:{nl:"Tessalonica",en:"Thessalonica"},region:{nl:"Macedonië",en:"Macedonia"},desc:{nl:"Hoofdstad van Macedonië waar Paulus een gemeente stichtte.",en:"Capital of Macedonia where Paul founded a church."},story:{nl:"Paulus predikte drie sabbatten lang in de synagoge van Tessalonica, waarna een oproer ontstond (Handelingen 17:1-9). Hij schreef later twee brieven aan de gemeente. De stad lag aan de Via Egnatia en bestaat nog als Thessaloniki.",en:"Paul preached for three sabbaths in the synagogue of Thessalonica, after which a riot broke out (Acts 17:1-9). He later wrote two letters to the church. The city lay on the Via Egnatia and still exists as Thessaloniki."},verses:["Handelingen 17:1", "1 Tessalonicenzen 1:1", "Filippenzen 4:16"],eras:[6]},{id:"syracuse",coords:[37.063889,15.293056],name:{nl:"Syracuse",en:"Syracuse"},region:{nl:"Sicilië",en:"Sicily"},desc:{nl:"Havenstad op Sicilië waar Paulus drie dagen bleef op weg naar Rome.",en:"Port city in Sicily where Paul stayed three days on his way to Rome."},story:{nl:"Op weg naar Rome legde het schip waarmee Paulus reisde aan in Syracuse op Sicilië, waar zij drie dagen bleven (Handelingen 28:12). Syracuse was in de oudheid een van de grootste steden van de Griekse wereld.",en:"On the way to Rome the ship Paul travelled on put in at Syracuse in Sicily, where they stayed three days (Acts 28:12). Syracuse was one of the largest cities of the Greek world in antiquity."},verses:["Handelingen 28:12"],eras:[6]},{id:"puteoli",coords:[40.826111,14.120556],name:{nl:"Puteoli",en:"Puteoli"},region:{nl:"Italië (Campanië)",en:"Italy (Campania)"},desc:{nl:"Haven waar Paulus Italië binnenkwam en zeven dagen bij broeders bleef.",en:"Harbour where Paul entered Italy and stayed seven days with brothers."},story:{nl:"In Puteoli, de belangrijkste graanhaven van Rome, ging Paulus aan land. Hij trof er broeders en bleef zeven dagen; daarna ging hij te voet naar Rome (Handelingen 28:13-14).",en:"At Puteoli, Rome's main grain harbour, Paul came ashore. He found brothers there and stayed seven days; then he went to Rome on foot (Acts 28:13-14)."},verses:["Handelingen 28:13", "Handelingen 28:14"],eras:[6]},{id:"salamis",coords:[35.184944,33.901944],name:{nl:"Salamis",en:"Salamis"},region:{nl:"Cyprus",en:"Cyprus"},desc:{nl:"Havenstad op Cyprus waar Paulus en Barnabas de synagogen bezochten.",en:"Port city on Cyprus where Paul and Barnabas visited the synagogues."},story:{nl:"Paulus en Barnabas landden op Cyprus in Salamis en verkondigden het woord van God in de synagogen (Handelingen 13:5). Barnabas kwam zelf van Cyprus (Handelingen 4:36). Vandaar trokken zij over het eiland naar Pafos.",en:"Paul and Barnabas landed on Cyprus at Salamis and proclaimed the word of God in the synagogues (Acts 13:5). Barnabas himself came from Cyprus (Acts 4:36). From there they crossed the island to Paphos."},verses:["Handelingen 13:5"],eras:[6]},{id:"thebes",coords:[25.720556,32.610278],name:{nl:"Thebe (No-Amon)",en:"Thebes (No-Amon)"},region:{nl:"Boven-Egypte",en:"Upper Egypt"},desc:{nl:"Oude hoofdstad van Boven-Egypte, tempelstad van Amon.",en:"Ancient capital of Upper Egypt, temple city of Amun."},story:{nl:"Thebe (No-Amon, het huidige Luxor en Karnak) was de religieuze hoofdstad van Egypte en de stad van de god Amon. De profeten kondigden haar val aan (Nahum 3:8-10, Jeremia 46:25, Ezechiël 30:14-16). Assyrië plunderde de stad in 663 v.Chr.",en:"Thebes (No-Amon, modern Luxor and Karnak) was the religious capital of Egypt and the city of the god Amun. The prophets announced its fall (Nahum 3:8-10, Jeremiah 46:25, Ezekiel 30:14-16). Assyria sacked the city in 663 BC."},verses:["Nahum 3:8", "Jeremia 46:25", "Ezechiël 30:14"],eras:[4, 5]},{id:"on",coords:[30.108086,31.33822],name:{nl:"On (Heliopolis)",en:"On (Heliopolis)"},region:{nl:"Beneden-Egypte",en:"Lower Egypt"},desc:{nl:"Zonnestad waar de priester woonde wiens dochter Josefs vrouw werd.",en:"City of the sun where the priest lived whose daughter became Joseph's wife."},story:{nl:"On (Heliopolis, \"stad van de zon\") was een van de oudste godsdienstige centra van Egypte. Farao gaf Josef Asnath, de dochter van Potifera, de priester van On, als vrouw (Genesis 41:45). Hun zonen Manasse en Efraïm werden hier geboren (Genesis 46:20).",en:"On (Heliopolis, \"city of the sun\") was one of the oldest religious centres of Egypt. Pharaoh gave Joseph Asenath, the daughter of Potiphera, priest of On, as his wife (Genesis 41:45). Their sons Manasseh and Ephraim were born here (Genesis 46:20)."},verses:["Genesis 41:45", "Genesis 46:20"],eras:[1, 2]},{id:"tahpanhes",coords:[30.860556,32.171389],name:{nl:"Tachpanhes",en:"Tahpanhes"},region:{nl:"Egypte (Nijldelta)",en:"Egypt (Nile Delta)"},desc:{nl:"Egyptische grensstad waar Jeremia heen werd gebracht na de val van Jeruzalem.",en:"Egyptian border city to which Jeremiah was taken after the fall of Jerusalem."},story:{nl:"Na de moord op Gedalja vluchtte een groep Judeeërs naar Egypte en nam Jeremia mee naar Tachpanhes (Jeremia 43:7). Daar verborg hij stenen in het plaveisel voor Farao's paleis en profeteerde dat Nebukadnezar Egypte zou binnenvallen (Jeremia 43:8-13).",en:"After the murder of Gedaliah a group of Judeans fled to Egypt and took Jeremiah to Tahpanhes (Jeremiah 43:7). There he hid stones in the pavement before Pharaoh's palace and prophesied that Nebuchadnezzar would invade Egypt (Jeremiah 43:8-13)."},verses:["Jeremia 43:7", "Jeremia 43:9", "Jeremia 44:1"],eras:[5]},{id:"syene",coords:[24.066181,32.895862],name:{nl:"Syene",en:"Syene"},region:{nl:"Zuid-Egypte",en:"Southern Egypt"},desc:{nl:"Zuidgrens van Egypte, het huidige Aswan.",en:"Southern border of Egypt, modern Aswan."},story:{nl:"Syene (het huidige Aswan) lag bij de eerste Nijlcatarakt. Ezechiël spreekt over Egypte \"van Migdol tot Syene\" (Ezechiël 29:10, 30:6), de uitersten van het land van noord tot zuid.",en:"Syene (modern Aswan) lay by the first Nile cataract. Ezekiel speaks of Egypt \"from Migdol to Syene\" (Ezekiel 29:10, 30:6), the extremes of the land from north to south."},verses:["Ezechiël 29:10", "Ezechiël 30:6"],eras:[5]},{id:"calah",coords:[36.142884,43.312178],name:{nl:"Kalach",en:"Calah"},region:{nl:"Assyrië",en:"Assyria"},desc:{nl:"Assyrische hoofdstad, gebouwd door Nimrod.",en:"Assyrian capital, built by Nimrod."},story:{nl:"Kalach (het huidige Nimrud) wordt in Genesis 10:11-12 genoemd als stad die door Assur werd gebouwd. Het was in de negende eeuw v.Chr. de hoofdstad van het Assyrische rijk onder Assurnasirpal II. De opgravingen leverden enorme paleizen en reliëfs op; in 2015 werd veel verwoest.",en:"Calah (modern Nimrud) is mentioned in Genesis 10:11-12 as a city built by Asshur. In the ninth century BC it was the capital of the Assyrian empire under Ashurnasirpal II. Excavations yielded enormous palaces and reliefs; much was destroyed in 2015."},verses:["Genesis 10:11", "Genesis 10:12"],eras:[1, 4]},{id:"erech",coords:[32.322222,45.636111],name:{nl:"Erech (Uruk)",en:"Erech (Uruk)"},region:{nl:"Mesopotamië",en:"Mesopotamia"},desc:{nl:"Een van de oudste steden ter wereld, begin van Nimrods rijk.",en:"One of the oldest cities in the world, the beginning of Nimrod's kingdom."},story:{nl:"Erech (Uruk) was een van de eerste grote steden van Mesopotamië en wordt in Genesis 10:10 genoemd als begin van het rijk van Nimrod. Hier is een van de oudste schriftsystemen ontstaan; het Gilgamesj-epos is aan deze stad verbonden.",en:"Erech (Uruk) was one of the first great cities of Mesopotamia and is mentioned in Genesis 10:10 as the beginning of Nimrod's kingdom. One of the earliest writing systems emerged here; the Epic of Gilgamesh is connected with this city."},verses:["Genesis 10:10", "Ezra 4:9"],eras:[1]},{id:"ecbatana",coords:[34.798311,48.514966],name:{nl:"Ecbatana",en:"Ecbatana"},region:{nl:"Medië (Perzië)",en:"Media (Persia)"},desc:{nl:"Zomerhoofdstad van de Perzische koningen, waar het besluit van Cyrus werd gevonden.",en:"Summer capital of the Persian kings, where the decree of Cyrus was found."},story:{nl:"In Ecbatana (Achmeta) werd de boekrol met het besluit van Cyrus gevonden, waarmee de Joden mochten terugkeren en de tempel herbouwen (Ezra 6:2-5). De stad was de zomerresidentie van de Perzische koningen; hier ligt het huidige Hamadan in Iran.",en:"In Ecbatana (Achmetha) the scroll with the decree of Cyrus was found, which allowed the Jews to return and rebuild the temple (Ezra 6:2-5). The city was the summer residence of the Persian kings; modern Hamadan in Iran lies here."},verses:["Ezra 6:2"],eras:[5]},{id:"asshur",coords:[35.456667,43.2625],name:{nl:"Assur",en:"Asshur"},region:{nl:"Assyrië",en:"Assyria"},desc:{nl:"Oorspronkelijke hoofdstad en godsdienstige hart van Assyrië.",en:"Original capital and religious heart of Assyria."},story:{nl:"Assur aan de Tigris was de oudste hoofdstad van het Assyrische rijk en het religieuze centrum rond de god Assur. Het wordt in Genesis 10:11 en Ezechiël 27:23 genoemd. Latere koningen verplaatsten het bestuur naar Kalach en Nineve.",en:"Asshur on the Tigris was the oldest capital of the Assyrian empire and the religious centre around the god Ashur. It is mentioned in Genesis 10:11 and Ezekiel 27:23. Later kings moved the government to Calah and Nineveh."},verses:["Genesis 10:11", "Ezechiël 27:23"],eras:[1, 4]},{id:"cyrene",coords:[32.820946,21.851229],name:{nl:"Cyrene",en:"Cyrene"},region:{nl:"Noord-Afrika (Libië)",en:"North Africa (Libya)"},desc:{nl:"Stad van Simon die het kruis van Jezus droeg.",en:"City of Simon who carried the cross of Jesus."},story:{nl:"Cyrene was een Griekse stad in het huidige Libië met een grote Joodse gemeenschap. Simon van Cyrene werd gedwongen het kruis van Jezus te dragen (Mattheüs 27:32). Mensen uit Cyrene waren bij het Pinksterfeest (Handelingen 2:10) en Lucius van Cyrene was profeet en leraar in Antiochië (Handelingen 13:1).",en:"Cyrene was a Greek city in modern Libya with a large Jewish community. Simon of Cyrene was forced to carry the cross of Jesus (Matthew 27:32). People from Cyrene were at the Feast of Pentecost (Acts 2:10) and Lucius of Cyrene was a prophet and teacher in Antioch (Acts 13:1)."},verses:["Mattheüs 27:32", "Handelingen 2:10", "Handelingen 13:1"],eras:[6]}];export{T as C,A as M};
